# ==============================================================================
# PERFIS E COORDENADAS TERRITORIAIS OFICIAIS DE CAMPO GRANDE - MS (SISGRAN / PLANURB)
# ==============================================================================
# ARQUIVO GERADO AUTOMATICAMENTE a partir de:
#   - geojson/bairros.geojson (74 Bairros Oficiais do Plano Diretor)
#   - geojson/pd-macrozonas-urbanas.geojson (Macrozonas Urbanas LC 341/2018)
#   - geojson/parcelamentos.geojson (894 parcelamentos e loteamentos da PLANURB)
#   - PostGIS: 20.000 Imóveis Cadastrais Oficiais com Ruas Reais
#
# Para atualizar: python scripts/gerar_perfis_sisgran.py
# ==============================================================================
import unicodedata
from typing import Dict, Any, Tuple, Optional, List

TOTAL_BAIRROS_OFICIAIS = 74

class PerfisSisgranDict(dict):
    """Dicionário inteligente de perfis territoriais: permite acesso por nome canônico ou variação case-insensitive."""
    def __getitem__(self, key):
        if dict.__contains__(self, key):
            return super().__getitem__(key)
        res = resolver_bairro(key)
        if res and dict.__contains__(self, res):
            return super().__getitem__(res)
        raise KeyError(key)

    def get(self, key, default=None):
        if dict.__contains__(self, key):
            return super().get(key, default)
        res = resolver_bairro(key)
        if res and dict.__contains__(self, res):
            return super().get(res, default)
        return default

    def __contains__(self, key):
        if dict.__contains__(self, key):
            return True
        res = resolver_bairro(key)
        return bool(res and dict.__contains__(self, res))


class CoordenadasBairrosDict(dict):
    """Dicionário inteligente de coordenadas: permite busca por nome canônico ou variação case-insensitive."""
    def __getitem__(self, key):
        if dict.__contains__(self, key):
            return super().__getitem__(key)
        res = resolver_bairro(key)
        if res and dict.__contains__(self, res):
            return super().__getitem__(res)
        raise KeyError(key)

    def get(self, key, default=None):
        if dict.__contains__(self, key):
            return super().get(key, default)
        res = resolver_bairro(key)
        if res and dict.__contains__(self, res):
            return super().get(res, default)
        return default

    def __contains__(self, key):
        if dict.__contains__(self, key):
            return True
        res = resolver_bairro(key)
        return bool(res and dict.__contains__(self, res))


