# --- app/static/js/main.js ---
cat > 'app/static/js/main.js' <<'OMNI_EOF'
document.addEventListener('DOMContentLoaded', function () {
  // 1. Sidebar Toggle (Mobile Drawer & Desktop Collapse)
  const sidebarToggle = document.getElementById('sidebarToggle');
  const sidebar = document.getElementById('sidebar');
  const sidebarBackdrop = document.getElementById('sidebarBackdrop');
  const appWrapper = document.querySelector('.app-wrapper') || document.body;

  // Função para gerenciar tooltips nos ícones do menu lateral quando recolhido
  function updateSidebarTooltips() {
    const isCollapsed = appWrapper && appWrapper.classList.contains('sidebar-collapsed');
    const links = document.querySelectorAll('.sidebar-link');
    links.forEach(function (link) {
      const existingTooltip = bootstrap.Tooltip.getInstance(link);
      if (isCollapsed && window.innerWidth >= 992) {
        if (!existingTooltip && link.getAttribute('title')) {
          new bootstrap.Tooltip(link, {
            placement: 'right',
            trigger: 'hover',
            boundary: 'window'
          });
        }
      } else {
        if (existingTooltip) {
          existingTooltip.dispose();
        }
      }
    });
  }

  // Restaurar estado recolhido no desktop via localStorage
  if (appWrapper && window.innerWidth >= 992) {
    if (localStorage.getItem('sidebar_collapsed') === 'true') {
      appWrapper.classList.add('sidebar-collapsed');
    }
  }
  updateSidebarTooltips();
  window.addEventListener('resize', updateSidebarTooltips);

  if (sidebarToggle && sidebar) {
    sidebarToggle.addEventListener('click', function () {
      if (window.innerWidth < 992) {
        // Modo Mobile: Abre/fecha drawer com backdrop
        sidebar.classList.toggle('show');
        if (sidebarBackdrop) sidebarBackdrop.classList.toggle('show');
      } else {
        // Modo Desktop: Recolhe/expande barra lateral (modo compacto com apenas ícones)
        if (appWrapper) {
          appWrapper.classList.toggle('sidebar-collapsed');
          const isCollapsed = appWrapper.classList.contains('sidebar-collapsed');
          localStorage.setItem('sidebar_collapsed', isCollapsed ? 'true' : 'false');
          updateSidebarTooltips();
          // Dispara resize para Leaflet e gráficos se adaptarem perfeitamente
          setTimeout(function () {
            window.dispatchEvent(new Event('resize'));
          }, 280);
        }
      }
    });

    if (sidebarBackdrop) {
      sidebarBackdrop.addEventListener('click', function () {
        sidebar.classList.remove('show');
        sidebarBackdrop.classList.remove('show');
      });
    }
  }

  // 2. Auto-dismiss flash alerts after 6 seconds
  const alerts = document.querySelectorAll('.alert-dismissible');
  alerts.forEach(function (alert) {
    setTimeout(function () {
      const bsAlert = bootstrap.Alert.getOrCreateInstance(alert);
      if (bsAlert) {
        bsAlert.close();
      }
    }, 6000);
  });

  // 3. Generic Delete Confirmation Modal Handler
  const deleteModal = document.getElementById('deleteConfirmModal');
  if (deleteModal) {
    deleteModal.addEventListener('show.bs.modal', function (event) {
      const button = event.relatedTarget;
      if (!button) return;

      const actionUrl = button.getAttribute('data-action');
      const itemName = button.getAttribute('data-name') || 'este registro';
      const itemType = button.getAttribute('data-type') || 'item';

      const form = deleteModal.querySelector('#deleteConfirmForm');
      const textSpan = deleteModal.querySelector('#deleteItemName');
      const typeSpan = deleteModal.querySelector('#deleteItemType');

      if (form && actionUrl) form.action = actionUrl;
      if (textSpan) textSpan.textContent = itemName;
      if (typeSpan) typeSpan.textContent = itemType;
    });
  }

  // 4. Input Masks (CPF/CNPJ, Telefone, CEP)
  const docInput = document.getElementById('documento');
  if (docInput) {
    docInput.addEventListener('input', function (e) {
      let v = e.target.value.replace(/\D/g, '');
      if (v.length <= 11) {
        // CPF: 000.000.000-00
        v = v.replace(/(\d{3})(\d)/, '$1.$2');
        v = v.replace(/(\d{3})(\d)/, '$1.$2');
        v = v.replace(/(\d{3})(\d{1,2})$/, '$1-$2');
      } else {
        // CNPJ: 00.000.000/0000-00
        v = v.substring(0, 14);
        v = v.replace(/^(\d{2})(\d)/, '$1.$2');
        v = v.replace(/^(\d{2})\.(\d{3})(\d)/, '$1.$2');
        v = v.replace(/\.(\d{3})(\d)/, '.$1/$2');
        v = v.replace(/(\d{4})(\d)/, '$1-$2');
      }
      e.target.value = v;
    });
  }

  const phoneInput = document.getElementById('telefone');
  if (phoneInput) {
    phoneInput.addEventListener('input', function (e) {
      let v = e.target.value.replace(/\D/g, '').substring(0, 11);
      if (v.length > 10) {
        // (11) 98765-4321
        v = v.replace(/^(\d{2})(\d{5})(\d{4})$/, '($1) $2-$3');
      } else if (v.length > 5) {
        // (11) 8765-4321
        v = v.replace(/^(\d{2})(\d{4})(\d{0,4})$/, '($1) $2-$3');
      } else if (v.length > 2) {
        v = v.replace(/^(\d{2})(\d{0,5})$/, '($1) $2');
      }
      e.target.value = v;
    });
  }

  const cepInput = document.getElementById('cep');
  if (cepInput) {
    cepInput.addEventListener('input', function (e) {
      let v = e.target.value.replace(/\D/g, '').substring(0, 8);
      if (v.length > 5) {
        v = v.replace(/^(\d{5})(\d{1,3})$/, '$1-$2');
      }
      e.target.value = v;
    });

    // Optional: Auto-fill ViaCEP
    cepInput.addEventListener('blur', function () {
      const cep = this.value.replace(/\D/g, '');
      if (cep.length === 8) {
        fetch(`https://viacep.com.br/ws/${cep}/json/`)
          .then(res => res.json())
          .then(data => {
            if (!data.erro) {
              const logradouro = document.getElementById('logradouro');
              const bairro = document.getElementById('bairro');
              const cidade = document.getElementById('cidade');
              const estado = document.getElementById('estado');

              if (logradouro && !logradouro.value) logradouro.value = data.logradouro;
              if (bairro && !bairro.value) bairro.value = data.bairro;
              if (cidade && !cidade.value) cidade.value = data.localidade;
              if (estado && !estado.value) estado.value = data.uf;

              const numInput = document.getElementById('numero');
              if (numInput) numInput.focus();
            }
          })
          .catch(() => {});
      }
    });
  }

  // 5. Initialize Bootstrap tooltips
  const tooltipTriggerList = [].slice.call(document.querySelectorAll('[data-bs-toggle="tooltip"]'));
  tooltipTriggerList.map(function (tooltipTriggerEl) {
    return new bootstrap.Tooltip(tooltipTriggerEl);
  });

  // 6. Theme Switcher (Claro / Escuro com persistência via localStorage)
  const themeToggle = document.getElementById('themeToggle');
  const dropdownThemeToggle = document.getElementById('dropdownThemeToggle');
  const themeIcon = document.getElementById('themeIcon');
  const dropdownThemeBadge = document.getElementById('dropdownThemeBadge');

  function applyTheme(theme) {
    document.documentElement.setAttribute('data-bs-theme', theme);
    localStorage.setItem('digitalnet_theme', theme);

    if (themeIcon) {
      if (theme === 'dark') {
        themeIcon.className = 'bi bi-sun-fill text-warning fs-6';
      } else {
        themeIcon.className = 'bi bi-moon-stars-fill text-warning fs-6';
      }
    }
    if (dropdownThemeBadge) {
      dropdownThemeBadge.textContent = theme === 'dark' ? 'Escuro' : 'Claro';
      dropdownThemeBadge.className = theme === 'dark' ? 'badge bg-warning text-dark' : 'badge bg-secondary';
    }
    if (themeToggle) {
      themeToggle.setAttribute('title', theme === 'dark' ? 'Alternar para Tema Claro' : 'Alternar para Tema Escuro');
    }
  }

  // Sincronizar estado inicial dos botões com o tema ativo
  const currentTheme = document.documentElement.getAttribute('data-bs-theme') || localStorage.getItem('digitalnet_theme') || 'light';
  applyTheme(currentTheme);

  function toggleTheme() {
    const activeTheme = document.documentElement.getAttribute('data-bs-theme') || 'light';
    const nextTheme = activeTheme === 'dark' ? 'light' : 'dark';
    applyTheme(nextTheme);
  }

  if (themeToggle) {
    themeToggle.addEventListener('click', toggleTheme);
  }
  if (dropdownThemeToggle) {
    dropdownThemeToggle.addEventListener('click', toggleTheme);
  }
});
OMNI_EOF

# --- app/templates/admin/grupos/form.html ---
cat > 'app/templates/admin/grupos/form.html' <<'OMNI_EOF'
{% extends "base.html" %}

{% block title %}{{ titulo }} - Administração DigitalNet{% endblock %}

{% block content %}
<div class="mb-4">
  <nav aria-label="breadcrumb">
    <ol class="breadcrumb small mb-1">
      <li class="breadcrumb-item"><span class="text-muted">Administração</span></li>
      <li class="breadcrumb-item"><a href="{{ url_for('admin.grupos') }}" class="text-decoration-none">Grupos de Acesso</a></li>
      <li class="breadcrumb-item active" aria-current="page">{{ titulo }}</li>
    </ol>
  </nav>
  <div class="d-flex align-items-center justify-content-between">
    <div>
      <h2 class="fw-bold mb-0 text-dark">{{ titulo }}</h2>
      <p class="text-muted small mb-0">Configure as permissões coletivas e atribua usuários a este grupo</p>
    </div>
    <a href="{{ url_for('admin.grupos') }}" class="btn btn-outline-secondary btn-sm">
      <i class="bi bi-arrow-left"></i> Voltar aos Grupos
    </a>
  </div>
</div>

<div class="row justify-content-center">
  <div class="col-lg-8">
    <form method="POST" novalidate>
      {{ form.hidden_tag() }}

      <!-- CARD 1: DADOS DO GRUPO -->
      <div class="card-custom p-4 mb-4 bg-white">
        <h5 class="fw-bold text-dark mb-3 pb-2 border-bottom d-flex align-items-center gap-2">
          <i class="bi bi-shield-check text-primary"></i> Definição do Grupo
        </h5>

        <div class="row g-3">
          <div class="col-md-7">
            <label for="nome" class="form-label">{{ form.nome.label.text }}</label>
            {{ form.nome(class="form-control" + (" is-invalid" if form.nome.errors else ""), placeholder="Ex: Comercial Telecom MS, Suporte N2, etc.") }}
            {% for error in form.nome.errors %}
              <div class="invalid-feedback">{{ error }}</div>
            {% endfor %}
          </div>

          <div class="col-md-5">
            <label for="papel" class="form-label fw-bold">{{ form.papel.label.text }}</label>
            {{ form.papel(class="form-select" + (" is-invalid" if form.papel.errors else "")) }}
            {% for error in form.papel.errors %}
              <div class="invalid-feedback">{{ error }}</div>
            {% endfor %}
            <small class="text-muted" style="font-size: 0.72rem;">Papel herdado pelos membros deste grupo</small>
          </div>

          <div class="col-md-12">
            <label for="descricao" class="form-label">{{ form.descricao.label.text }}</label>
            {{ form.descricao(class="form-control" + (" is-invalid" if form.descricao.errors else ""), rows=2, placeholder="Descreva os objetivos deste grupo e escopo de atuação...") }}
            {% for error in form.descricao.errors %}
              <div class="invalid-feedback">{{ error }}</div>
            {% endfor %}
          </div>
        </div>
      </div>

      <!-- CARD 2: MEMBROS DO GRUPO -->
      <div class="card-custom p-4 mb-4 bg-white">
        <h5 class="fw-bold text-dark mb-3 pb-2 border-bottom d-flex align-items-center gap-2">
          <i class="bi bi-people-fill text-info"></i> Membros Integrantes
        </h5>

        <div class="mb-3">
          <p class="text-muted small mb-3">Marque os usuários que devem fazer parte deste grupo de acesso:</p>

          {% if usuarios %}
            <div class="row g-2" style="max-height: 320px; overflow-y: auto;">
              {% for u in usuarios %}
                <div class="col-md-6">
                  <div class="form-check p-2 border rounded bg-light d-flex align-items-center gap-2">
                    <input class="form-check-input ms-1" type="checkbox" name="membros" value="{{ u.id }}" id="membro_{{ u.id }}"
                           {% if form.membros.data and u.id in form.membros.data %}checked{% endif %}>
                    <label class="form-check-label w-100" for="membro_{{ u.id }}">
                      <strong class="d-block text-dark">{{ u.nome }}</strong>
                      <span class="text-muted small d-block">@{{ u.username }} &bull; Perfil: {{ u.perfil_nome }}</span>
                    </label>
                  </div>
                </div>
              {% endfor %}
            </div>
          {% else %}
            <div class="alert alert-secondary small mb-0">Nenhum usuário ativo disponível para vinculação.</div>
          {% endif %}
        </div>
      </div>

      <!-- SUBMIT BAR -->
      <div class="d-flex align-items-center justify-content-end gap-2 mb-5">
        <a href="{{ url_for('admin.grupos') }}" class="btn btn-light-custom px-4">Cancelar</a>
        <button type="submit" class="btn btn-primary-custom px-4">
          <i class="bi bi-check-lg"></i> {{ acao }}
        </button>
      </div>
    </form>
  </div>
</div>
{% endblock %}
OMNI_EOF

