# --- app/templates/leads/detail.html ---
cat > 'app/templates/leads/detail.html' <<'OMNI_EOF'
{% extends "base.html" %}

{% block title %}Dossiê Comercial & Central WhatsApp - {{ lead.empresa }} - DigitalNet MS{% endblock %}

{% block content %}
<div class="container-fluid px-0">

  <!-- BREADCRUMB & VOLTAR -->
  <div class="d-flex justify-content-between align-items-center mb-3">
    <a href="{{ url_for('leads.index', bairro=lead.bairro) }}" class="btn btn-dn-outline btn-sm shadow-sm">
      <i class="bi bi-arrow-left me-1"></i> Voltar ao Radar de Leads
    </a>

    <div class="d-flex gap-2">
      <span class="badge {{ lead.status_badge_class }} py-2 px-3 fs-6 shadow-sm">
        Status: {{ lead.status_label }}
      </span>
      {% if lead.optin_status == 'aceito' %}
      <span class="badge bg-success py-2 px-3 fs-6 shadow-sm">
        <i class="bi bi-shield-check me-1"></i> Opt-in Aceito
      </span>
      {% elif lead.optin_status == 'recusado' %}
      <span class="badge bg-danger py-2 px-3 fs-6 shadow-sm">
        Opt-in Recusado
      </span>
      {% else %}
      <span class="badge bg-warning text-dark py-2 px-3 fs-6 shadow-sm">
        <i class="bi bi-clock-history me-1"></i> Opt-in Pendente
      </span>
      {% endif %}
    </div>
  </div>

  <!-- HERO BANNER DO LEAD COM IDENTIDADE DIGITALNET -->
  <div class="dn-hero-banner mb-4">
    <div class="row align-items-center">
      <div class="col-lg-8">
        <div class="d-flex align-items-center gap-3 mb-2">
          <div class="rounded-circle p-3 d-flex align-items-center justify-content-center shadow" style="background: rgba(255, 190, 24, 0.2); color: var(--dn-yellow-gold); width: 64px; height: 64px;">
            <i class="bi bi-building fs-2"></i>
          </div>
          <div>
            <h2 class="h3 fw-bold mb-1 text-white">{{ lead.empresa }}</h2>
            <div class="text-white-50 small d-flex align-items-center gap-2 flex-wrap">
              <span><i class="bi bi-person-fill text-warning me-1"></i> Decisor: <strong class="text-white">{{ lead.nome }}</strong></span>
              {% if lead.cargo %}
              <span class="badge" style="background: rgba(255, 190, 24, 0.25); color: #fde047; font-weight: 600;">{{ lead.cargo }}</span>
              {% endif %}
              <span>&bull; <i class="bi bi-tag-fill text-warning me-1"></i> {{ lead.niche }}</span>
            </div>
          </div>
        </div>

        <div class="d-flex flex-wrap gap-4 text-white-50 small mt-3 pt-3 border-top" style="border-color: rgba(255, 255, 255, 0.15) !important;">
          <div><i class="bi bi-geo-alt-fill text-danger me-1"></i> <span class="text-white">{{ lead.endereco_resumido }}</span></div>
          {% if lead.telefone %}
          <div><i class="bi bi-telephone-fill text-success me-1"></i> <span class="text-white">{{ lead.telefone }}</span></div>
          {% endif %}
          {% if lead.email %}
          <div><i class="bi bi-envelope-fill text-info me-1"></i> <span class="text-white">{{ lead.email }}</span></div>
          {% endif %}
          <div><i class="bi bi-hdd-network text-warning me-1"></i> Operadora Atual: <strong class="text-white">{{ lead.operadora_atual }}</strong></div>
        </div>
      </div>

      <div class="col-lg-4 text-lg-end mt-3 mt-lg-0">
        <div class="d-inline-block text-center p-3 rounded-3 shadow" style="background: rgba(9, 28, 54, 0.6); border: 1px solid rgba(255, 190, 24, 0.3); min-width: 170px;">
          <small class="text-white-50 d-block text-uppercase fw-semibold" style="font-size: 0.7rem; letter-spacing: 0.05em;">Score de Conversão</small>
          <h2 class="fw-bold mb-0 text-warning" style="font-size: 2.5rem;">{{ lead.lead_score }}<small class="fs-6 text-white-50">/100</small></h2>
          <small class="text-success fw-semibold"><i class="bi bi-check2-circle me-1"></i>Alta Viabilidade Óptica</small>
        </div>
      </div>
    </div>
  </div>

  <div class="row g-4">

    <!-- COLUNA ESQUERDA: CENTRAL WHATSAPP & QUEBRA DE OBJEÇÕES -->
    <div class="col-lg-7">

      <!-- CARD WHATSAPP ANTI-BAN -->
      <div class="card border-0 shadow-sm mb-4">
        <div class="card-header bg-white py-3 border-bottom d-flex justify-content-between align-items-center">
          <div class="d-flex align-items-center gap-2">
            <div class="p-2 rounded-2 text-white" style="background: #25d366;">
              <i class="bi bi-whatsapp fs-5"></i>
            </div>
            <div>
              <h5 class="fw-bold mb-0 text-dark">Abordagem WhatsApp com Opt-in Anti-Ban</h5>
              <small class="text-muted">Mensagem consultiva sem links promocionais no primeiro contato</small>
            </div>
          </div>
          <span class="badge py-2 px-3 rounded-pill" style="background: #ecfdf5; color: #065f46; border: 1px solid #a7f3d0; font-weight: 700;">
            <i class="bi bi-shield-check me-1"></i> Blindado contra Ban
          </span>
        </div>
        
        <div class="card-body p-4">
          <div class="alert alert-light border py-2 px-3 small mb-3 text-secondary">
            <i class="bi bi-info-circle text-primary me-1"></i>
            Este roteiro segue o método de 3 passos: <strong>1)</strong> Gancho hiperlocal em Campo Grande, <strong>2)</strong> Comparativo contra a operadora atual e <strong>3)</strong> Pedido de consentimento explícito.
          </div>

          <div class="position-relative mb-3">
            <textarea id="scriptWhatsApp" class="form-control bg-light border text-dark font-monospace small p-3" rows="8" readonly style="line-height: 1.5; resize: none;">{{ lead.icebreaker_optin }}</textarea>
            <button class="btn btn-sm btn-outline-secondary position-absolute top-0 end-0 m-2 shadow-sm" onclick="copiarScript()" title="Copiar para área de transferência">
              <i class="bi bi-clipboard me-1"></i> Copiar
            </button>
          </div>

          <div class="d-flex flex-wrap gap-2 justify-content-between align-items-center pt-2">
            {% if lead.whatsapp_url != '#' %}
            <a href="{{ lead.whatsapp_url }}" target="_blank" class="btn btn-success px-4 shadow-sm" id="btnDispararWhatsApp">
              <i class="bi bi-whatsapp me-2"></i> Abrir WhatsApp Web
            </a>
            {% else %}
            <button class="btn btn-secondary" disabled>Sem telefone cadastrado</button>
            {% endif %}

            <div class="d-flex gap-2">
              <form action="{{ url_for('leads.atualizar_status', lead_id=lead.id) }}" method="POST" class="d-inline">
                <input type="hidden" name="status" value="optin_solicitado">
                <input type="hidden" name="optin_status" value="pendente">
                <button type="submit" class="btn btn-sm btn-outline-warning text-dark fw-semibold" title="Marcar que enviou mensagem">
                  <i class="bi bi-send me-1"></i> Marcar Enviado
                </button>
              </form>

              <form action="{{ url_for('leads.atualizar_status', lead_id=lead.id) }}" method="POST" class="d-inline">
                <input type="hidden" name="status" value="optin_aceito">
                <input type="hidden" name="optin_status" value="aceito">
                <button type="submit" class="btn btn-sm btn-dn-blue" title="Lead respondeu com interesse">
                  <i class="bi bi-check-circle-fill text-warning me-1"></i> Opt-in Aceito!
                </button>
              </form>
            </div>
          </div>
        </div>
      </div>

      <!-- TUTOR DE QUEBRA DE OBJEÇÕES -->
      <div class="card border-0 shadow-sm mb-4">
        <div class="card-header bg-white py-3 border-bottom">
          <div class="d-flex align-items-center gap-2">
            <div class="p-2 rounded-2 text-dark" style="background: var(--dn-yellow-gold);">
              <i class="bi bi-mortarboard-fill fs-5"></i>
            </div>
            <div>
              <h5 class="fw-bold mb-0 text-dark">Tutor de Quebra de Objeções (SDR Telecom)</h5>
              <small class="text-muted">Selecione a objeção do cliente para obter a técnica psicológica e o script imediato</small>
            </div>
          </div>
        </div>

        <div class="card-body p-4">
          <div class="btn-group btn-group-sm w-100 mb-3 shadow-sm" role="group">
            <a href="{{ url_for('leads.detail', lead_id=lead.id, obj='fidelidade') }}" class="btn {% if obj_key == 'fidelidade' %}btn-dn-yellow{% else %}btn-outline-secondary{% endif %}">
              Fidelidade Concorrente
            </a>
            <a href="{{ url_for('leads.detail', lead_id=lead.id, obj='preco') }}" class="btn {% if obj_key == 'preco' %}btn-dn-yellow{% else %}btn-outline-secondary{% endif %}">
              Preço / Custo
            </a>
            <a href="{{ url_for('leads.detail', lead_id=lead.id, obj='marca') }}" class="btn {% if obj_key == 'marca' %}btn-dn-yellow{% else %}btn-outline-secondary{% endif %}">
              Não Conheço a Marca
            </a>
            <a href="{{ url_for('leads.detail', lead_id=lead.id, obj='satisfeito') }}" class="btn {% if obj_key == 'satisfeito' %}btn-dn-yellow{% else %}btn-outline-secondary{% endif %}">
              Já Estou Satisfeito
            </a>
          </div>

          <div class="p-3 bg-light rounded-3 border mb-2">
            <div class="d-flex justify-content-between align-items-start mb-2 flex-wrap gap-1">
              <h6 class="fw-bold mb-0 text-dark"><i class="bi bi-chat-quote-fill me-1 text-warning"></i>{{ tutor_obj.titulo }}</h6>
              <span class="badge py-1 px-2 rounded-pill bg-dark text-white">Técnica: {{ tutor_obj.tecnica }}</span>
            </div>
            
            <p class="small text-muted mb-2"><strong>Diagnóstico Psicológico:</strong> {{ tutor_obj.diagnostico }}</p>
            
            <div class="p-3 bg-white rounded border border-warning font-monospace small text-dark mt-2 shadow-sm" style="border-left: 4px solid var(--dn-yellow) !important;">
              {{ tutor_obj.script_whatsapp|replace('\n', '<br>')|safe }}
            </div>
          </div>
        </div>
      </div>

    </div>

    <!-- COLUNA DIREITA: VIABILIDADE & CONVERSÃO EM CLIENTE -->
    <div class="col-lg-5">

      <!-- DIAGNÓSTICO E DOR -->
      <div class="card border-0 shadow-sm mb-4">
        <div class="card-header bg-white py-3 border-bottom">
          <div class="d-flex align-items-center gap-2">
            <i class="bi bi-speedometer2 fs-5 text-primary"></i>
            <h5 class="fw-bold mb-0 text-dark">Diagnóstico da Conexão Atual</h5>
          </div>
        </div>
        
        <div class="card-body p-4">
          <div class="mb-3">
            <label class="small fw-bold text-muted text-uppercase d-block mb-1">Principal Gargalo / Dor Mapeada:</label>
            <div class="alert alert-warning border-warning bg-warning bg-opacity-10 small mb-0 py-2">
              <i class="bi bi-exclamation-triangle-fill text-warning-emphasis me-2"></i>
              <strong class="text-dark">{{ lead.dor_principal or "Lentidão nas maquininhas e lentidão no sinal Wi-Fi durante os horários de pico." }}</strong>
            </div>
          </div>

          <div class="mb-3">
            <label class="small fw-bold text-muted text-uppercase d-block mb-1">Viabilidade Óptica no Bairro (DigitalNet MS):</label>
            <div class="d-flex align-items-center gap-3 p-3 bg-light rounded-3 border">
              <div class="p-2 rounded-circle bg-success bg-opacity-10 text-success">
                <i class="bi bi-check-circle-fill fs-4"></i>
              </div>
              <div>
                <strong class="text-dark d-block">Porta Óptica Confirmada no Bairro {{ lead.bairro }}</strong>
                <div class="text-muted" style="font-size: 0.75rem;">Rede FTTH própria AS61588. Instalação rápida inclusa sem obras.</div>
              </div>
            </div>
          </div>

          <div class="border-top pt-3">
            <label class="small fw-bold text-muted text-uppercase d-block mb-1">Plano Recomendado DigitalNet:</label>
            <h5 class="fw-bold mb-1" style="color: var(--dn-blue);">{{ lead.plano_sugerido }}</h5>
            <div class="text-muted small">Valor mensal: <strong class="text-dark fs-6">R$ {{ "%.2f"|format(lead.valor_mensal_sugerido)|replace('.', ',') }}</strong> com roteador Wi-Fi 6 em comodato.</div>
          </div>
        </div>
      </div>

      <!-- FORMULÁRIO DE CONVERSÃO EM CLIENTE (DIGITALNET THEMED) -->
      <div class="card border-0 shadow-sm" style="border-top: 4px solid var(--dn-yellow) !important;">
        <div class="card-header bg-white py-3 border-bottom">
          <div class="d-flex align-items-center gap-2">
            <i class="bi bi-person-check-fill fs-5" style="color: var(--dn-blue);"></i>
            <div>
              <h5 class="fw-bold mb-0 text-dark">Fechar Venda & Ativar Assinatura</h5>
              <small class="text-muted">Cria o Cliente e gera o Pedido de instalação no banco de dados</small>
            </div>
          </div>
        </div>
        
        <div class="card-body p-4">
          <form action="{{ url_for('leads.converter_cliente', lead_id=lead.id) }}" method="POST">
            <div class="mb-3">
              <label class="form-label small fw-bold text-dark d-flex justify-content-between align-items-center">
                <span>Plano Oficial da DigitalNet Contratado *</span>
                <span class="badge bg-light text-primary border" id="badgePlanoTipo">Residencial / B2B</span>
              </label>
              <select name="plano_id" class="form-select bg-light fw-semibold" id="selectPlano">
                {% for p in planos %}
                <option value="{{ p.id }}"
                        data-nome="{{ p.nome }}"
                        data-preco="{{ '%.2f'|format(p.valor_mensal) }}"
                        data-tipo="{{ p.tipo_nome }}"
                        data-velocidade="{{ p.velocidade_formatada }}"
                        data-wifi="{{ p.roteador_wifi or 'Instalação com Wi-Fi 6 em comodato' }}"
                        {% if p.nome == lead.plano_sugerido or (lead.plano_sugerido and p.nome.lower() in lead.plano_sugerido.lower()) %}selected{% endif %}>
                  [{{ p.tipo }}] {{ p.nome }} ({{ p.velocidade_download }} Mega) — R$ {{ "%.2f"|format(p.valor_mensal)|replace('.', ',') }}/mês
                </option>
                {% endfor %}
              </select>
              <input type="hidden" name="plano_sugerido" id="hiddenPlanoNome" value="{{ lead.plano_sugerido }}">
            </div>

            <!-- DETALHES DO PLANO SELECIONADO -->
            <div class="p-3 bg-light rounded-3 border mb-3" id="boxPlanoPreview">
              <div class="d-flex align-items-center justify-content-between mb-1">
                <span class="small fw-bold text-dark" id="previewPlanoVelocidade">Velocidade: Carregando...</span>
                <span class="badge bg-success-subtle text-success small" id="previewPlanoPreco">R$ 0,00/mês</span>
              </div>
              <div class="small text-muted" id="previewPlanoWifi">
                <i class="bi bi-router text-primary me-1"></i> Roteador Wi-Fi 6 em Comodato
              </div>
            </div>

            <div class="mb-3">
              <label class="form-label small fw-bold text-dark">Valor Acordado da Mensalidade (R$)</label>
              <div class="input-group">
                <span class="input-group-text bg-white text-dark fw-bold">R$</span>
                <input type="number" step="0.01" name="valor_mensal_sugerido" id="inputValor" class="form-control bg-light fw-bold text-success fs-6" value="{{ '%.2f'|format(lead.valor_mensal_sugerido) }}" required>
              </div>
              <small class="text-muted" style="font-size: 0.75rem;">Você pode conceder desconto promocional ou manter a tabela oficial.</small>
            </div>

            <div class="alert alert-info border-info bg-info bg-opacity-10 small mb-3 py-2">
              <i class="bi bi-info-circle-fill text-info me-1"></i>
              Ao validar a conversão, o lead é registrado como <strong>Cliente</strong> e um <strong>Pedido de Ativação</strong> vinculado a este plano será gerado automaticamente.
            </div>

            <button type="submit" class="btn btn-dn-yellow w-100 py-3 fw-bold shadow-sm" style="font-size: 1rem;">
              <i class="bi bi-check2-circle me-2"></i> Converter em Cliente & Ativar Pedido
            </button>
          </form>
        </div>
      </div>

    </div>

  </div>

</div>

<script>
function copiarScript() {
  const textarea = document.getElementById('scriptWhatsApp');
  textarea.select();
  textarea.setSelectionRange(0, 99999);
  navigator.clipboard.writeText(textarea.value).then(() => {
    alert('Script de WhatsApp copiado para a área de transferência!');
  });
}

function atualizarPreviewPlano() {
  const select = document.getElementById('selectPlano');
  if (!select) return;
  const opt = select.options[select.selectedIndex];
  if (!opt) return;

  const preco = opt.getAttribute('data-preco');
  const nome = opt.getAttribute('data-nome');
  const tipo = opt.getAttribute('data-tipo');
  const vel = opt.getAttribute('data-velocidade');
  const wifi = opt.getAttribute('data-wifi');

  if (preco) {
    document.getElementById('inputValor').value = preco;
    const precoFormatado = 'R$ ' + parseFloat(preco).toFixed(2).replace('.', ',') + '/mês';
    const previewPreco = document.getElementById('previewPlanoPreco');
    if (previewPreco) previewPreco.textContent = precoFormatado;
  }
  if (nome) {
    const hiddenNome = document.getElementById('hiddenPlanoNome');
    if (hiddenNome) hiddenNome.value = nome;
  }
  if (tipo) {
    const badgeTipo = document.getElementById('badgePlanoTipo');
    if (badgeTipo) badgeTipo.textContent = tipo;
  }
  if (vel) {
    const previewVel = document.getElementById('previewPlanoVelocidade');
    if (previewVel) previewVel.textContent = 'Velocidade: ' + vel;
  }
  if (wifi) {
    const previewWifi = document.getElementById('previewPlanoWifi');
    if (previewWifi) previewWifi.innerHTML = '<i class="bi bi-router text-primary me-1"></i> ' + wifi;
  }
}

const selectPlanoEl = document.getElementById('selectPlano');
if (selectPlanoEl) {
  selectPlanoEl.addEventListener('change', atualizarPreviewPlano);
  atualizarPreviewPlano();
}
</script>
{% endblock %}
OMNI_EOF

# --- app/templates/leads/index.html ---
cat > 'app/templates/leads/index.html' <<'OMNI_EOF'
{% extends "base.html" %}

{% block title %}Radar de Leads Telecom & Expansão de Fibra - DigitalNet MS{% endblock %}

{% block extra_css %}
<!-- Leaflet CSS para o Mapa de Calor -->
<link rel="stylesheet" href="https://unpkg.com/leaflet@1.9.4/dist/leaflet.css" integrity="sha256-p4NxAoJBhIIN+hmNHrzRCf9tD/miZyoHS5obTRR9BMY=" crossorigin="" />
<style>
  .leaflet-popup-content-wrapper {
    border-radius: 12px;
    box-shadow: 0 12px 30px rgba(15, 45, 87, 0.22);
    padding: 0;
    overflow: hidden;
    border: 1px solid #e2e8f0;
  }
  .leaflet-popup-content {
    margin: 0 !important;
    line-height: 1.4;
  }
  .leaflet-container {
    font-family: 'Plus Jakarta Sans', sans-serif !important;
  }
  .heat-badge-chip {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    font-size: 0.75rem;
    font-weight: 600;
    padding: 4px 10px;
    border-radius: 20px;
  }
  .custom-pin-fibra {
    background: #1b4f99;
    color: #ffffff;
    border: 2px solid #ffffff;
    border-radius: 50%;
    width: 32px;
    height: 32px;
    display: flex;
    align-items: center;
    justify-content: center;
    box-shadow: 0 4px 12px rgba(27, 79, 153, 0.45);
    font-size: 0.85rem;
  }
  .custom-pin-lead {
    background: #f59e0b;
    color: #0f172a;
    border: 2px solid #ffffff;
    border-radius: 50%;
    width: 28px;
    height: 28px;
    display: flex;
    align-items: center;
    justify-content: center;
    box-shadow: 0 4px 10px rgba(245, 158, 11, 0.5);
    font-size: 0.75rem;
    font-weight: bold;
  }
  .custom-pin-lead.high-score {
    background: #ef4444;
    color: #ffffff;
    box-shadow: 0 4px 12px rgba(239, 68, 68, 0.55);
  }
</style>
{% endblock %}

{% block content %}
<div class="container-fluid px-0">

  <!-- CABEÇALHO COM IDENTIDADE DIGITALNET -->
  <div class="d-flex flex-column flex-md-row justify-content-between align-items-start align-items-md-center gap-3 mb-4">
    <div>
      <div class="d-flex align-items-center gap-2 flex-wrap">
        <h1 class="h3 mb-0 dn-header-title">Radar de Prospecção & Expansão de Fibra</h1>
        <span class="badge py-2 px-3 dn-badge-corp rounded-pill">
          <i class="bi bi-broadcast-pin text-warning me-1"></i> DigitalNet MS &bull; Campo Grande
        </span>
      </div>
      <p class="text-muted small mb-0 mt-1">
        Geo-prospecção inteligente na mesma região dos clientes ativos com abordagem anti-ban e opt-in via WhatsApp.
      </p>
    </div>

    <div class="d-flex align-items-center gap-2">
      <button class="btn btn-outline-primary btn-sm" type="button" data-bs-toggle="collapse" data-bs-target="#comoFunciona" aria-expanded="false">
        <i class="bi bi-shield-check text-warning me-1"></i> Blindagem Anti-Ban
      </button>
      <button class="btn btn-dn-yellow btn-sm px-3 shadow-sm" data-bs-toggle="modal" data-bs-target="#modalProspectar">
        <i class="bi bi-lightning-charge-fill me-1"></i> Nova Prospecção Geo
      </button>
    </div>
  </div>

  <!-- BOX EXPLICATIVO ANTI-BAN (COLLAPSIBLE) -->
  <div class="collapse mb-4" id="comoFunciona">
    <div class="card border-0 shadow-sm rounded-3" style="background: linear-gradient(135deg, #0f2d57, #1b4f99); color: #ffffff;">
      <div class="card-body p-4">
        <div class="d-flex align-items-center gap-2 mb-3">
          <i class="bi bi-shield-lock-fill fs-4 text-warning"></i>
          <h5 class="fw-bold mb-0 text-white">Estratégia Anti-Ban & Prospecção por Nós Ópticos</h5>
        </div>
        <div class="row g-3 small">
          <div class="col-md-4">
            <div class="p-3 rounded-3" style="background: rgba(255, 255, 255, 0.08);">
              <strong class="text-warning d-block mb-1"><i class="bi bi-geo-alt-fill me-1"></i>1. Viabilidade por Vizinhos:</strong>
              Prospecta apenas em quarteirões onde a DigitalNet já possui clientes ativos. Custo de instalação mínimo e viabilidade técnica garantida no poste.
            </div>
          </div>
          <div class="col-md-4">
            <div class="p-3 rounded-3" style="background: rgba(255, 255, 255, 0.08);">
              <strong class="text-warning d-block mb-1"><i class="bi bi-router-fill me-1"></i>2. Oferta Superior à Concorrência:</strong>
              Aborda com argumentos imbatíveis contra Vivo/Claro: roteador Wi-Fi 6 comodato, pontos extras DigiMesh, upload de 50% e suporte 24h presencial em Campo Grande.
            </div>
          </div>
          <div class="col-md-4">
            <div class="p-3 rounded-3" style="background: rgba(255, 255, 255, 0.08);">
              <strong class="text-warning d-block mb-1"><i class="bi bi-chat-check-fill me-1"></i>3. Opt-in Conversacional Obrigatório:</strong>
              O primeiro contato nunca envia links externos nem arquivos pesados. Pede permissão explícita para enviar o comparativo, blindando o WhatsApp contra bans.
            </div>
          </div>
        </div>
      </div>
    </div>
  </div>

  <!-- SEÇÃO 6x6: MAPA DE CALOR & RADAR DE BAIRROS (CLUSTERS) -->
  <div class="row g-4 mb-4 align-items-stretch">
    <!-- COLUNA 1 (6x12): MAPA DE CALOR -->
    <div class="col-lg-6 d-flex flex-column">
      <div class="card border-0 shadow-sm h-100 overflow-hidden d-flex flex-column" id="cardMapaCalor">
        <div class="card-header bg-white py-3 border-bottom d-flex flex-column flex-sm-row justify-content-between align-items-start align-items-sm-center gap-2">
          <div class="d-flex align-items-center gap-2">
            <div class="p-2 rounded-3" style="background: #fef3c7; color: #b45309;">
              <i class="bi bi-fire fs-5"></i>
            </div>
            <div>
              <h5 class="fw-bold mb-0 text-dark">
                Mapa de Calor: Cobertura Óptica
              </h5>
              <small class="text-muted">Concentração geo-espacial e oportunidades em Campo Grande</small>
            </div>
          </div>

          <div class="d-flex align-items-center gap-2 flex-wrap">
            <div class="btn-group btn-group-sm shadow-sm" role="group">
              <button type="button" class="btn btn-outline-secondary active" id="btnFiltroTodos" onclick="filtrarMapa('todos')">
                <i class="bi bi-grid-fill me-1"></i> Todos
              </button>
              <button type="button" class="btn btn-outline-secondary" id="btnFiltroFibra" onclick="filtrarMapa('fibra')">
                <i class="bi bi-broadcast text-primary me-1"></i> Fibra
              </button>
              <button type="button" class="btn btn-outline-secondary" id="btnFiltroLeads" onclick="filtrarMapa('leads')">
                <i class="bi bi-fire text-warning me-1"></i> Oportunidades
              </button>
            </div>

            <!-- MENU DROPDOWN DE CAMADAS GEOJSON (BAIRROS, MACROZONAS, PARCELAMENTOS) -->
            <div class="dropdown">
              <button class="btn btn-sm btn-outline-primary dropdown-toggle shadow-sm" type="button" id="btnCamadasGeo" data-bs-toggle="dropdown" data-bs-auto-close="outside" aria-expanded="false">
                <i class="bi bi-layers-fill me-1"></i> Camadas Geo
                <span id="badgeCamadasAtivas" class="badge bg-primary rounded-pill ms-1 d-none">0</span>
              </button>
              <div class="dropdown-menu dropdown-menu-end shadow-lg p-3 border-0 rounded-3" style="min-width: 270px; z-index: 1050;">
                <div class="d-flex align-items-center justify-content-between mb-2 pb-2 border-bottom">
                  <h6 class="fw-bold mb-0 text-dark small">
                    <i class="bi bi-map me-1 text-primary"></i> Camadas Municipais (CG)
                  </h6>
                  <span id="geoLoadingSpinner" class="spinner-border spinner-border-sm text-primary d-none" role="status"></span>
                </div>

                <div class="form-check form-switch mb-2">
                  <input class="form-check-input" type="checkbox" id="checkGeoBairros" onchange="toggleCamadaGeo('bairros', this.checked)">
                  <label class="form-check-label small fw-semibold text-dark" for="checkGeoBairros">
                    <span class="d-inline-block rounded-circle me-1" style="width: 10px; height: 10px; background: #1b4f99;"></span>
                    Bairros de Campo Grande
                  </label>
                  <div class="text-muted" style="font-size: 0.72rem; padding-left: 2px;">74 regiões urbanas e limites</div>
                </div>

                <div class="form-check form-switch mb-2">
                  <input class="form-check-input" type="checkbox" id="checkGeoMacrozonas" onchange="toggleCamadaGeo('macrozonas', this.checked)">
                  <label class="form-check-label small fw-semibold text-dark" for="checkGeoMacrozonas">
                    <span class="d-inline-block rounded-circle me-1" style="width: 10px; height: 10px; background: #0284c7;"></span>
                    Macrozonas (Plano Diretor)
                  </label>
                  <div class="text-muted" style="font-size: 0.72rem; padding-left: 2px;">Zoneamento e uso do solo</div>
                </div>

                <div class="form-check form-switch mb-0">
                  <input class="form-check-input" type="checkbox" id="checkGeoParcelamentos" onchange="toggleCamadaGeo('parcelamentos', this.checked)">
                  <label class="form-check-label small fw-semibold text-dark" for="checkGeoParcelamentos">
                    <span class="d-inline-block rounded-circle me-1" style="width: 10px; height: 10px; background: #d97706;"></span>
                    Parcelamentos / Loteamentos
                  </label>
                  <div class="text-muted" style="font-size: 0.72rem; padding-left: 2px;">894 parcelamentos (PLANURB)</div>
                </div>

                <div class="mt-3 pt-2 border-top">
                  <div class="d-flex align-items-center justify-content-between mb-2">
                    <span class="fw-bold small text-dark"><i class="bi bi-globe2 me-1 text-primary"></i> Estilo do Mapa</span>
                    {% if mapbox_api_key %}
                    <span class="badge bg-success bg-opacity-10 text-success border border-success-subtle" style="font-size: 0.65rem;">Mapbox Ativo</span>
                    {% else %}
                    <span class="badge bg-secondary bg-opacity-10 text-secondary border" style="font-size: 0.65rem;">OpenStreetMap</span>
                    {% endif %}
                  </div>
                  <div class="btn-group btn-group-sm w-100" role="group">
                    <input type="radio" class="btn-check" name="baseMapStyle" id="baseMapRuas" autocomplete="off" checked onchange="definirCamadaBase('ruas')">
                    <label class="btn btn-outline-secondary" for="baseMapRuas">Ruas</label>

                    {% if mapbox_api_key %}
                    <input type="radio" class="btn-check" name="baseMapStyle" id="baseMapSatelite" autocomplete="off" onchange="definirCamadaBase('satelite')">
                    <label class="btn btn-outline-secondary" for="baseMapSatelite"><i class="bi bi-camera me-1"></i>Satélite</label>
                    {% endif %}

                    <input type="radio" class="btn-check" name="baseMapStyle" id="baseMapOSM" autocomplete="off" onchange="definirCamadaBase('osm')">
                    <label class="btn btn-outline-secondary" for="baseMapOSM">OSM</label>
                  </div>
                </div>
              </div>
            </div>

            <button type="button" class="btn btn-sm btn-light border shadow-sm" onclick="centralizarCampoGrande()" title="Centralizar em Campo Grande">
              <i class="bi bi-crosshair me-1"></i> Recentralizar
            </button>

            <button type="button" class="btn btn-sm btn-light border shadow-sm" id="btnToggleFullscreenMap" onclick="toggleFullscreenMapa()" title="Alternar Modo Tela Cheia">
              <i class="bi bi-arrows-fullscreen me-1" id="iconFullscreenMap"></i> <span id="labelFullscreenMap" class="d-none d-sm-inline">Tela Cheia</span>
            </button>
          </div>
        </div>

        <!-- LEGENDA DO MAPA DE CALOR -->
        <div class="px-3 py-2 bg-light border-bottom d-flex align-items-center justify-content-between flex-wrap gap-2 small heat-legend-bar">
          <div class="d-flex align-items-center gap-2 flex-wrap">
            <span class="heat-badge-chip bg-white border py-1 px-2">
              <span style="width: 10px; height: 10px; border-radius: 50%; background: #1b4f99; display: inline-block;"></span>
              CTO Ativa
            </span>
            <span class="heat-badge-chip bg-white border py-1 px-2">
              <span style="width: 10px; height: 10px; border-radius: 50%; background: #f59e0b; display: inline-block;"></span>
              Lead (80-89)
            </span>
            <span class="heat-badge-chip bg-white border py-1 px-2">
              <span style="width: 10px; height: 10px; border-radius: 50%; background: #ef4444; display: inline-block;"></span>
              Prioridade (90+)
            </span>
          </div>
          <div class="text-muted small">
            <i class="bi bi-cursor me-1 text-primary"></i> Clique no ponto para WhatsApp/dossiê
          </div>
        </div>

        <!-- CONTAINER LEAFLET -->
        <div class="position-relative flex-grow-1 map-wrapper-inner" style="min-height: 480px;">
          <div id="mapaCalor" style="height: 100%; min-height: 480px; width: 100%; z-index: 1;"></div>
        </div>
      </div>
    </div>

    <!-- COLUNA 2 (6x12): RADAR DE BAIRROS (CLUSTERS) -->
    <div class="col-lg-6 d-flex flex-column">
      <div class="card border-0 shadow-sm h-100 d-flex flex-column">
        <div class="card-header bg-white py-3 border-bottom d-flex justify-content-between align-items-center">
          <div class="d-flex align-items-center gap-2">
            <div class="p-2 rounded-3" style="background: #e8f0fe; color: var(--dn-blue);">
              <i class="bi bi-geo-alt-fill fs-5"></i>
            </div>
            <div>
              <h5 class="fw-bold mb-0 text-dark">Clusters de Cobertura Óptica</h5>
              <small class="text-muted">Bairros com clientes ativos DigitalNet</small>
            </div>
          </div>
          <span class="badge py-2 px-3 rounded-pill bg-light text-dark border fw-semibold">
            <i class="bi bi-pin-map-fill text-primary me-1"></i> {{ clusters|length }} Regiões Mapeadas
          </span>
        </div>
        <div class="card-body p-3 bg-light flex-grow-1 overflow-auto" style="max-height: 560px;">
          <div class="row g-3">
            {% for c in clusters %}
            <div class="col-sm-6">
              <div class="dn-cluster-card {% if bairro_selecionado == c.bairro %}active-cluster{% endif %} h-100 d-flex flex-column">
                <div class="d-flex justify-content-between align-items-start mb-2">
                  <h6 class="fw-bold mb-0 text-dark">{{ c.bairro }}</h6>
                  <span class="badge py-1 px-2 rounded-pill" style="background: #e0f2fe; color: #0369a1; font-size: 0.7rem; font-weight: 700;">
                    <i class="bi bi-check-circle-fill me-1 text-success"></i>{{ c.viabilidade_estimada }}
                  </span>
                </div>
                
                <div class="small text-muted mb-2">
                  <i class="bi bi-building text-secondary me-1"></i> {{ c.cidade }} &bull; {{ c.estado }}
                </div>

                <div class="d-flex justify-content-between text-muted small py-2 my-2 border-top border-bottom">
                  <span><strong class="text-dark">{{ c.total_clientes }}</strong> ativos</span>
                  <span><strong class="text-primary">{{ c.total_leads }}</strong> leads</span>
                </div>

                <div class="d-flex gap-2 mt-auto pt-2">
                  <a href="{{ url_for('leads.index', bairro=c.bairro) }}" class="btn btn-sm btn-outline-secondary flex-fill" title="Ver leads deste bairro">
                    <i class="bi bi-funnel me-1"></i> Filtrar
                  </a>
                  <form action="{{ url_for('leads.prospectar_regiao') }}" method="POST" class="d-inline flex-fill">
                    <input type="hidden" name="bairro" value="{{ c.bairro }}">
                    <input type="hidden" name="cidade" value="{{ c.cidade }}">
                    <input type="hidden" name="count" value="4">
                    <button type="submit" class="btn btn-sm btn-dn-blue w-100" title="Gerar mais leads vizinhos com IA">
                      <i class="bi bi-lightning-charge-fill text-warning me-1"></i> Prospectar
                    </button>
                  </form>
                </div>
              </div>
            </div>
            {% endfor %}
          </div>
        </div>
      </div>
    </div>
  </div>

  <!-- MÉTRICAS DO FUNIL DE LEADS (KPI CARDS DIGITALNET) -->
  <div class="row g-3 mb-4">
    <div class="col-xl-2 col-md-4 col-6">
      <div class="dn-kpi-card" style="border-top: 3px solid var(--dn-blue);">
        <span class="kpi-label">Total Leads</span>
        <div class="kpi-number" style="color: var(--dn-blue);">{{ total_leads }}</div>
      </div>
    </div>
    <div class="col-xl-2 col-md-4 col-6">
      <div class="dn-kpi-card" style="border-top: 3px solid #64748b;">
        <span class="kpi-label">Novos / Fila</span>
        <div class="kpi-number" style="color: #475569;">{{ total_novos }}</div>
      </div>
    </div>
    <div class="col-xl-2 col-md-4 col-6">
      <div class="dn-kpi-card" style="border-top: 3px solid var(--dn-yellow);">
        <span class="kpi-label">Opt-in Enviado</span>
        <div class="kpi-number" style="color: var(--dn-yellow-dark);">{{ total_optin_solicitado }}</div>
      </div>
    </div>
    <div class="col-xl-2 col-md-4 col-6">
      <div class="dn-kpi-card" style="border-top: 3px solid #0284c7;">
        <span class="kpi-label">Opt-in Aceito</span>
        <div class="kpi-number" style="color: #0284c7;">{{ total_optin_aceito }}</div>
      </div>
    </div>
    <div class="col-xl-2 col-md-4 col-6">
      <div class="dn-kpi-card" style="border-top: 3px solid #2563eb;">
        <span class="kpi-label">Proposta Enviada</span>
        <div class="kpi-number" style="color: #2563eb;">{{ total_proposta }}</div>
      </div>
    </div>
    <div class="col-xl-2 col-md-4 col-6">
      <div class="dn-kpi-card" style="border-top: 3px solid #10b981;">
        <span class="kpi-label">Convertidos</span>
        <div class="kpi-number" style="color: #059669;">{{ total_convertidos }}</div>
      </div>
    </div>
  </div>

  <!-- FILTROS E TABELA DE LEADS -->
  <div class="card border-0 shadow-sm mb-4">
    <div class="card-header bg-white py-3 border-bottom">
      <form method="GET" action="{{ url_for('leads.index') }}" class="row g-2 align-items-center">
        <div class="col-md-4">
          <div class="input-group input-group-sm">
            <span class="input-group-text bg-light text-muted border-end-0"><i class="bi bi-search"></i></span>
            <input type="text" id="filtroRapidoLeads" name="busca" class="form-control border-start-0 bg-light" placeholder="Buscar por empresa, decisor, rua..." value="{{ busca }}">
          </div>
        </div>
        <div class="col-md-3">
          <select name="bairro" class="form-select form-select-sm bg-light">
            <option value="">Todos os Bairros</option>
            {% for c in clusters %}
            <option value="{{ c.bairro }}" {% if bairro_selecionado == c.bairro %}selected{% endif %}>{{ c.bairro }} ({{ c.total_clientes }} clientes)</option>
            {% endfor %}
          </select>
        </div>
        <div class="col-md-3">
          <select name="status" class="form-select form-select-sm bg-light">
            <option value="">Todos os Status</option>
            <option value="novo" {% if status_selecionado == 'novo' %}selected{% endif %}>Novo Lead</option>
            <option value="optin_solicitado" {% if status_selecionado == 'optin_solicitado' %}selected{% endif %}>Opt-in Solicitado</option>
            <option value="optin_aceito" {% if status_selecionado == 'optin_aceito' %}selected{% endif %}>Opt-in Aceito</option>
            <option value="proposta_enviada" {% if status_selecionado == 'proposta_enviada' %}selected{% endif %}>Proposta Enviada</option>
            <option value="convertido" {% if status_selecionado == 'convertido' %}selected{% endif %}>Convertido</option>
          </select>
        </div>
        <div class="col-md-2 d-flex gap-2">
          <button type="submit" class="btn btn-sm btn-dn-blue flex-fill">
            <i class="bi bi-funnel-fill me-1"></i> Filtrar
          </button>
          {% if busca or bairro_selecionado or status_selecionado %}
          <a href="{{ url_for('leads.index') }}" class="btn btn-sm btn-outline-secondary" title="Limpar filtros">
            <i class="bi bi-x-lg"></i>
          </a>
          {% endif %}
        </div>
      </form>
    </div>

    <div class="table-responsive p-3">
      <table id="tabelaLeads" class="table table-hover align-middle mb-0 w-100">
        <thead class="dn-table-header">
          <tr>
            <th style="width: 1%;" class="text-center">Detalhes</th>
            <th class="ps-2">Lead / Empresa</th>
            <th>Localização (MS)</th>
            <th>Plano Recomendado</th>
            <th>Operadora Atual</th>
            <th>Score</th>
            <th>Opt-in WhatsApp</th>
            <th>Status</th>
            <th class="text-end pe-3">Ações</th>
          </tr>
        </thead>
        <tbody>
          {% if leads %}
            {% for l in leads %}
            <tr id="lead-tr-{{ l.id }}">
              <td class="text-center">
                <button type="button" class="btn btn-outline-primary btn-sm btn-details shadow-sm" title="Expandir dossiê e script anti-ban">
                  <i class="bi bi-chevron-down me-1"></i>Detalhes
                </button>
              </td>
              <td class="ps-2">
                <div class="fw-bold text-dark">{{ l.empresa }}</div>
                <small class="text-muted">{{ l.nome }} {% if l.cargo %}&bull; <span class="text-secondary">{{ l.cargo }}</span>{% endif %}</small>
              </td>
              <td>
                <span class="badge bg-light text-dark border"><i class="bi bi-geo-alt-fill text-danger me-1"></i>{{ l.bairro }}</span>
                <div class="small text-muted mt-1">{{ l.logradouro or 'Área Central' }}, {{ l.numero or 'S/N' }}</div>
              </td>
              <td>
                <div class="small fw-bold" style="color: var(--dn-blue);">{{ l.plano_sugerido }}</div>
                <small class="text-muted">R$ {{ "%.2f"|format(l.valor_mensal_sugerido)|replace('.', ',') }}/mês</small>
              </td>
              <td>
                <span class="badge bg-secondary bg-opacity-10 text-dark border" style="font-size: 0.75rem;">{{ l.operadora_atual }}</span>
              </td>
              <td>
                <span class="badge {% if l.lead_score >= 90 %}bg-danger text-white{% elif l.lead_score >= 80 %}bg-primary text-white{% else %}bg-warning text-dark{% endif %} px-2 py-1">
                  {{ l.lead_score }} pts
                </span>
              </td>
              <td>
                {% if l.optin_status == 'aceito' %}
                <span class="badge bg-success"><i class="bi bi-check-circle-fill me-1"></i>Opt-in Aceito</span>
                {% elif l.optin_status == 'recusado' %}
                <span class="badge bg-danger">Recusado</span>
                {% else %}
                <span class="badge bg-warning text-dark"><i class="bi bi-clock-history me-1"></i>Pendente</span>
                {% endif %}
              </td>
              <td>
                <span class="badge {{ l.status_badge_class }}">{{ l.status_label }}</span>
              </td>
              <td class="text-end pe-3">
                <div class="btn-group btn-group-sm">
                  {% if l.telefone and l.whatsapp_url != '#' %}
                  <a href="{{ l.whatsapp_url }}" target="_blank" class="btn btn-success" title="Iniciar Abordagem com Opt-in no WhatsApp Web">
                    <i class="bi bi-whatsapp"></i>
                  </a>
                  {% endif %}
                  <a href="{{ url_for('leads.detail', lead_id=l.id) }}" class="btn btn-dn-blue" title="Abrir Dossiê 360° e Quebra de Objeções">
                    <i class="bi bi-eye-fill me-1"></i> Dossiê
                  </a>
                </div>

                <!-- TEMPLATE EMBUTIDO DA LINHA ANINHADA ESTILO RESULTADO_TABLE.JS -->
                <div class="d-none row-details-content">
                  <div class="dt-child-row-container">
                    <div class="d-flex align-items-center justify-content-between mb-3 pb-2 border-bottom flex-wrap gap-2">
                      <div class="d-flex align-items-center gap-2 flex-wrap">
                        <span class="badge bg-warning text-dark fw-bold text-uppercase px-2 py-1" style="font-size: 0.72rem;">
                          <i class="bi bi-broadcast-pin me-1"></i> Radar Telecom
                        </span>
                        <strong class="text-dark fs-6">{{ l.empresa }}</strong>
                        <span class="badge bg-light text-secondary border">{{ l.bairro }} &bull; Campo Grande MS</span>
                        <span class="badge bg-primary-subtle text-primary fw-semibold">Score: {{ l.lead_score }} pts</span>
                      </div>
                      <div class="d-flex align-items-center gap-2 flex-wrap">
                        {% if l.telefone and l.whatsapp_url != '#' %}
                        <a href="{{ l.whatsapp_url }}" target="_blank" class="btn btn-sm btn-success shadow-sm">
                          <i class="bi bi-whatsapp me-1"></i> Abordar no WhatsApp
                        </a>
                        {% endif %}
                        <a href="{{ url_for('leads.detail', lead_id=l.id) }}" class="btn btn-sm btn-dn-blue">
                          <i class="bi bi-eye-fill me-1"></i> Dossiê 360°
                        </a>
                        <form action="{{ url_for('leads.converter_cliente', lead_id=l.id) }}" method="POST" class="d-flex align-items-center gap-1 flex-wrap">
                          <select name="plano_id" class="form-select form-select-sm bg-white border shadow-sm" style="max-width: 250px;" title="Selecione o plano oficial para este cliente">
                            {% for p in planos %}
                            <option value="{{ p.id }}" {% if p.nome == l.plano_sugerido or (l.plano_sugerido and p.nome.lower() in l.plano_sugerido.lower()) %}selected{% endif %}>
                              [{{ p.tipo }}] {{ p.nome }} ({{ p.velocidade_download }}M) - R$ {{ "%.2f"|format(p.valor_mensal)|replace('.', ',') }}
                            </option>
                            {% endfor %}
                          </select>
                          <button type="submit" class="btn btn-sm btn-primary-custom shadow-sm text-nowrap" onclick="return confirm('Deseja converter o lead {{ l.empresa }} em Cliente com o plano selecionado?');">
                            <i class="bi bi-check-circle-fill me-1"></i> Converter & Ativar
                          </button>
                        </form>
                      </div>
                    </div>

                    <!-- ACORDEÃO DE DETALHES ANINHADOS ESTILO RESULTADO_TABLE.JS -->
                    <div class="accordion" id="accordionLead-{{ l.id }}">

                      <!-- BLOCO 1: INTELIGÊNCIA TERRITORIAL & DADOS TÉCNICOS -->
                      <div class="card border-0 shadow-sm mb-2 rounded-3 overflow-hidden">
                        <div class="card-header collapsible-header py-2 px-3 bg-white" data-bs-toggle="collapse" data-bs-target="#collapseGeo-{{ l.id }}" style="cursor: pointer;">
                          <div class="d-flex align-items-center justify-content-between">
                            <div class="d-flex align-items-center gap-2">
                              <i class="bi bi-geo-alt-fill text-danger"></i>
                              <span class="fw-bold small text-dark">Inteligência Territorial & Viabilidade no Poste</span>
                            </div>
                            <span class="badge bg-success-subtle text-success small"><i class="bi bi-check-circle-fill me-1"></i>CTO Ativa no Quarteirão</span>
                          </div>
                        </div>
                        <div id="collapseGeo-{{ l.id }}" class="collapse show" data-bs-parent="#accordionLead-{{ l.id }}">
                          <div class="card-body p-0">
                            <div class="table-responsive">
                              <table class="table table-sm table-bordered mb-0 bg-white nested-table" style="font-size: 0.82rem;">
                                <tbody>
                                  <tr>
                                    <td class="bg-light text-muted fw-semibold" style="width: 22%;">Endereço Completo:</td>
                                    <td><strong>{{ l.logradouro or 'Área Central' }}, {{ l.numero or 'S/N' }}</strong> - Bairro: <strong>{{ l.bairro }}</strong>, {{ l.cidade }}/{{ l.estado }} {% if l.cep %}(CEP: {{ l.cep }}){% endif %}</td>
                                    <td class="bg-light text-muted fw-semibold" style="width: 20%;">Decisor / Contato:</td>
                                    <td><strong>{{ l.nome }}</strong> {% if l.cargo %}&bull; <span class="text-secondary">{{ l.cargo }}</span>{% endif %}</td>
                                  </tr>
                                  <tr>
                                    <td class="bg-light text-muted fw-semibold">Operadora Atual:</td>
                                    <td><span class="badge bg-danger-subtle text-danger fw-bold">{{ l.operadora_atual }}</span></td>
                                    <td class="bg-light text-muted fw-semibold">Nicho Comercial:</td>
                                    <td><strong class="text-primary">{{ l.niche or 'Geral' }}</strong></td>
                                  </tr>
                                  <tr>
                                    <td class="bg-light text-muted fw-semibold">Dor Principal Mapeada:</td>
                                    <td colspan="3" class="text-danger-emphasis fw-medium">
                                      {{ l.dor_principal or 'Instabilidade no link atual, oscilação no Wi-Fi e atendimento telefônico robotizado sem suporte presencial em Campo Grande.' }}
                                    </td>
                                  </tr>
                                </tbody>
                              </table>
                            </div>
                          </div>
                        </div>
                      </div>

                      <!-- BLOCO 2: SCRIPT DE ABORDAGEM BLINDADA WHATSAPP (ANTI-BAN) -->
                      <div class="card border-0 shadow-sm mb-2 rounded-3 overflow-hidden">
                        <div class="card-header collapsible-header py-2 px-3 bg-white" data-bs-toggle="collapse" data-bs-target="#collapseWpp-{{ l.id }}" style="cursor: pointer;">
                          <div class="d-flex align-items-center justify-content-between">
                            <div class="d-flex align-items-center gap-2">
                              <i class="bi bi-shield-check text-warning"></i>
                              <span class="fw-bold small text-dark">Blindagem Anti-Ban & Mensagem de Primeiro Contato</span>
                            </div>
                            <span class="badge {{ l.optin_badge_class }}">{{ l.optin_label }}</span>
                          </div>
                        </div>
                        <div id="collapseWpp-{{ l.id }}" class="collapse show" data-bs-parent="#accordionLead-{{ l.id }}">
                          <div class="card-body p-3 bg-white">
                            <div class="p-3 rounded-3 mb-2" style="background: #f0fdf4; border: 1px solid #bbf7d0; font-family: 'Courier New', Courier, monospace; font-size: 0.85rem; color: #166534; white-space: pre-wrap;">{{ l.icebreaker_optin or 'Mensagem de abordagem personalizada ainda não configurada para este lead.' }}</div>
                            <div class="d-flex align-items-center justify-content-between flex-wrap gap-2 pt-1">
                              <small class="text-muted">
                                <i class="bi bi-info-circle me-1"></i> Abordagem conversacional sem envio de links externos, evitando bloqueios na API do WhatsApp.
                              </small>
                              <div class="d-flex gap-2">
                                {% if l.icebreaker_optin %}
                                <button type="button" class="btn btn-sm btn-outline-secondary btn-copiar-script" data-script="{{ l.icebreaker_optin|e }}">
                                  <i class="bi bi-clipboard me-1"></i> Copiar Mensagem
                                </button>
                                {% endif %}
                                {% if l.telefone and l.whatsapp_url != '#' %}
                                <a href="{{ l.whatsapp_url }}" target="_blank" class="btn btn-sm btn-success">
                                  <i class="bi bi-whatsapp me-1"></i> Disparar via WhatsApp Web
                                </a>
                                {% endif %}
                              </div>
                            </div>
                          </div>
                        </div>
                      </div>

                      <!-- BLOCO 3: OFERTA RECOMENDADA DIGITALNET -->
                      <div class="card border-0 shadow-sm rounded-3 overflow-hidden">
                        <div class="card-header collapsible-header py-2 px-3 bg-white" data-bs-toggle="collapse" data-bs-target="#collapseOferta-{{ l.id }}" style="cursor: pointer;">
                          <div class="d-flex align-items-center justify-content-between">
                            <div class="d-flex align-items-center gap-2">
                              <i class="bi bi-router-fill text-primary"></i>
                              <span class="fw-bold small text-dark">Oferta Recomendada DigitalNet</span>
                            </div>
                            <span class="fw-bold text-success small">R$ {{ "%.2f"|format(l.valor_mensal_sugerido)|replace('.', ',') }}/mês</span>
                          </div>
                        </div>
                        <div id="collapseOferta-{{ l.id }}" class="collapse" data-bs-parent="#accordionLead-{{ l.id }}">
                          <div class="card-body p-0">
                            <div class="table-responsive">
                              <table class="table table-sm table-bordered mb-0 bg-white nested-table" style="font-size: 0.82rem;">
                                <tbody>
                                  <tr>
                                    <td class="bg-light text-muted fw-semibold" style="width: 22%;">Plano Sugerido:</td>
                                    <td><strong class="text-primary">{{ l.plano_sugerido }}</strong></td>
                                    <td class="bg-light text-muted fw-semibold" style="width: 20%;">Equipamento Incluso:</td>
                                    <td><span class="badge bg-warning text-dark fw-bold">Roteador Wi-Fi 6 em Comodato</span></td>
                                  </tr>
                                  <tr>
                                    <td class="bg-light text-muted fw-semibold">Valor Mensal:</td>
                                    <td class="text-success fw-bold">R$ {{ "%.2f"|format(l.valor_mensal_sugerido)|replace('.', ',') }}</td>
                                    <td class="bg-light text-muted fw-semibold">Diferencial Técnico:</td>
                                    <td>50% de Taxa de Upload garantida + Suporte presencial 24h em Campo Grande</td>
                                  </tr>
                                </tbody>
                              </table>
                            </div>
                          </div>
                        </div>
                      </div>

                    </div>
                  </div>
                </div>
              </td>
            </tr>
            {% endfor %}
          {% else %}
            <tr>
              <td colspan="9" class="text-center py-5 text-muted">
                <i class="bi bi-radar fs-1 d-block mb-3 text-secondary"></i>
                <p class="mb-2 fw-semibold text-dark">Nenhum lead encontrado para os filtros selecionados.</p>
                <small>Clique em <strong>"Nova Prospecção Geo"</strong> acima para mapear clientes em Campo Grande!</small>
              </td>
            </tr>
          {% endif %}
        </tbody>
      </table>
    </div>
  </div>

</div>

<!-- MODAL PROSPECTAR COM IA (TEMA DIGITALNET) -->
<div class="modal fade" id="modalProspectar" tabindex="-1" aria-labelledby="modalProspectarLabel" aria-hidden="true">
  <div class="modal-dialog">
    <div class="modal-content border-0 shadow-lg">
      <form action="{{ url_for('leads.prospectar_regiao') }}" method="POST">
        <div class="modal-header text-white" style="background: linear-gradient(135deg, var(--dn-blue-deep), var(--dn-blue));">
          <h5 class="modal-title" id="modalProspectarLabel">
            <i class="bi bi-radar me-2 text-warning"></i>Nova Prospecção Geo-Localizada
          </h5>
          <button type="button" class="btn-close btn-close-white" data-bs-dismiss="modal" aria-label="Fechar"></button>
        </div>
        <div class="modal-body p-4">
          <p class="small text-muted mb-3">
            O motor de IA identifica novos clientes potenciais no mesmo bairro onde a <strong>DigitalNet MS</strong> já possui rede óptica ativa, garantindo viabilidade e gerando o script anti-ban para WhatsApp.
          </p>

          <div class="mb-3">
            <label class="form-label small fw-bold text-dark">Bairro / Região em Campo Grande (MS)</label>
            <select name="bairro" class="form-select bg-light" required>
              <option value="Chácara Cachoeira">Chácara Cachoeira (Alta Densidade Empresarial / Clínicas)</option>
              <option value="Centro">Centro (Comércios, Escritórios e Contabilidades)</option>
              <option value="Santa Fé">Santa Fé (Boutiques, Estética e Consultórios)</option>
              <option value="Jardim dos Estados">Jardim dos Estados (Gastronomia e Escritórios)</option>
              <option value="Tiradentes">Tiradentes (Escolas, Academias e Varejo)</option>
              <option value="Vilas Boas">Vilas Boas (Comércio Local e Gastronomia)</option>
            </select>
          </div>

          <div class="mb-3">
            <label class="form-label small fw-bold text-dark">Nicho Comercial / Segmento</label>
            <input type="text" name="niche" class="form-control bg-light" value="Clínicas, Consultórios e Escritórios" required>
          </div>

          <div class="mb-3">
            <label class="form-label small fw-bold text-dark">Quantidade de Leads para Mapear</label>
            <select name="count" class="form-select bg-light">
              <option value="3">3 leads qualificados</option>
              <option value="5" selected>5 leads qualificados</option>
              <option value="8">8 leads qualificados</option>
            </select>
          </div>

          <div class="alert alert-warning border-warning bg-warning bg-opacity-10 py-2 small mb-0 d-flex align-items-center">
            <i class="bi bi-shield-check text-warning-emphasis fs-5 me-2"></i>
            <div>
              Cada lead virá com <strong>score de qualificação</strong>, <strong>dor mapeada</strong> e o <strong>script de opt-in de 1 clique</strong>.
            </div>
          </div>
        </div>
        <div class="modal-footer bg-light">
          <button type="button" class="btn btn-secondary btn-sm" data-bs-dismiss="modal">Cancelar</button>
          <button type="submit" class="btn btn-dn-blue btn-sm px-3 shadow-sm">
            <i class="bi bi-lightning-charge-fill text-warning me-1"></i> Iniciar Varredura de Leads
          </button>
        </div>
      </form>
    </div>
  </div>
</div>

<!-- OFFCANVAS: EMPRESAS NO RAIO DO NÓ ÓPTICO DIGITALNET -->
<div class="offcanvas offcanvas-end shadow-lg" tabindex="-1" id="offcanvasNodoEmpresas" aria-labelledby="offcanvasNodoLabel" style="width: 440px; max-width: 95vw; z-index: 1070;">
  <div class="offcanvas-header text-white" style="background: linear-gradient(135deg, #0f2d57, #1b4f99); border-bottom: 2px solid #fbbf24;">
    <div>
      <div class="d-flex align-items-center gap-2">
        <span class="badge py-1 px-2 rounded-pill" style="background: #fbbf24; color: #0f172a; font-weight: 700; font-size: 0.65rem;">
          <i class="bi bi-broadcast-pin me-1"></i> Nó Óptico DigitalNet
        </span>
        <span class="badge bg-white bg-opacity-20 text-white" style="font-size: 0.65rem;" id="offcanvasBadgeViabilidade">Viabilidade 99%</span>
      </div>
      <h5 class="offcanvas-title fw-bold text-white mt-1 mb-0" id="offcanvasNodoLabel">
        Empresas no Nó
      </h5>
      <small class="text-white text-opacity-75" style="font-size: 0.75rem;" id="offcanvasNodoSub">
        Cobertura direta no poste &bull; Campo Grande - MS
      </small>
    </div>
    <button type="button" class="btn-close btn-close-white" data-bs-dismiss="offcanvas" aria-label="Fechar"></button>
  </div>
  <div class="offcanvas-body p-3 bg-light">
    <div id="offcanvasLoading" class="text-center py-5 d-none">
      <div class="spinner-border text-primary mb-2" role="status"></div>
      <div class="fw-semibold text-dark small">Localizando empresas no raio da fibra...</div>
      <small class="text-muted">Cruzando dados RFB e inteligência territorial</small>
    </div>

    <div id="offcanvasConteudo">
      <div class="d-flex align-items-center justify-content-between mb-3 px-1">
        <span class="small text-muted" id="offcanvasTotalEmpresas">
          <strong>0</strong> empresas identificadas
        </span>
        <a href="#" id="offcanvasLinkFiltrarBairro" class="btn btn-sm btn-outline-primary" style="font-size: 0.72rem; padding: 3px 8px;">
          <i class="bi bi-funnel me-1"></i> Ver todas no Funil
        </a>
      </div>

      <div id="offcanvasListaEmpresas" class="d-flex flex-column gap-3">
        <!-- Cards dinâmicos inseridos via JS -->
      </div>
    </div>
  </div>
</div>
{% endblock %}

{% block extra_js %}
<!-- Leaflet JS para Renderização do Mapa de Calor -->
<script src="https://unpkg.com/leaflet@1.9.4/dist/leaflet.js" integrity="sha256-20nQCchB9co0qIjJZRGuk2/Z9VM+kNiyxNV1lvTlZBo=" crossorigin=""></script>
<script>
  // Dados passados pelo backend Flask
  const rawMapPoints = {{ map_points|tojson|safe }};
  const mapboxApiKey = {{ (mapbox_api_key or '')|tojson|safe }};
  const centroCG = [-20.4600, -54.5980];
  
  let mapInstance = null;
  let layerGroupFibra = null;
  let layerGroupLeads = null;
  let layerGroupHeat = null;
  let layerGroupNodoEmpresas = null;
  let currentBaseLayer = null;

  function initMap() {
    const mapContainer = document.getElementById('mapaCalor');
    if (!mapContainer || typeof L === 'undefined') return;

    // Inicializa o mapa Leaflet
    mapInstance = L.map('mapaCalor', {
      center: centroCG,
      zoom: 13,
      zoomControl: true,
      scrollWheelZoom: false
    });

    // Camada Base: Mapbox Streets (se chave configurada) ou OpenStreetMap sem marca d'água
    definirCamadaBase('ruas');

    // Painel customizado para camadas GeoJSON (abaixo dos pinos de leads e nós ópticos)
    if (!mapInstance.getPane('geojsonPane')) {
      mapInstance.createPane('geojsonPane');
      mapInstance.getPane('geojsonPane').style.zIndex = 350;
    }

    // Grupos de camadas
    layerGroupFibra = L.layerGroup().addTo(mapInstance);
    layerGroupLeads = L.layerGroup().addTo(mapInstance);
    layerGroupHeat = L.layerGroup().addTo(mapInstance);
    layerGroupNodoEmpresas = L.layerGroup().addTo(mapInstance);

    renderPoints();

    setTimeout(() => {
      if (mapInstance) {
        mapInstance.invalidateSize();
      }
    }, 200);
  }

  function renderPoints() {
    if (!mapInstance) return;

    layerGroupFibra.clearLayers();
    layerGroupLeads.clearLayers();
    layerGroupHeat.clearLayers();

    rawMapPoints.forEach(pt => {
      if (pt.tipo === 'cluster_fibra') {
        // Círculo de calor térmico para rede ativa
        const raio = 380 + (pt.clientes * 100);
        const heatCircle = L.circle([pt.lat, pt.lng], {
          radius: raio,
          color: '#1b4f99',
          fillColor: '#1b4f99',
          fillOpacity: 0.18,
          weight: 1.5,
          dashArray: '4, 4'
        });
        layerGroupHeat.addLayer(heatCircle);

        // Marcador do Nó Óptico
        const iconFibra = L.divIcon({
          className: 'custom-pin-fibra-wrapper',
          html: `<div class="custom-pin-fibra" title="${pt.titulo}"><i class="bi bi-broadcast"></i></div>`,
          iconSize: [32, 32],
          iconAnchor: [16, 16]
        });

        const marker = L.marker([pt.lat, pt.lng], { icon: iconFibra });

        // Hook de clique direto no Nó Óptico
        marker.on('click', function(e) {
          if (typeof window.onSelectNodoFibra === 'function') {
            window.onSelectNodoFibra(pt);
          }
        });

        const popupContent = `
          <div style="width: 260px;">
            <div style="background: linear-gradient(135deg, #0f2d57, #1b4f99); color: white; padding: 12px 14px;">
              <small style="color: #fbbf24; text-transform: uppercase; font-weight: 700; font-size: 0.7rem;">Nó de Fibra DigitalNet</small>
              <h6 style="margin: 0; font-weight: 700; font-size: 1rem;">${pt.bairro}</h6>
            </div>
            <div style="padding: 12px 14px; background: white; font-size: 0.85rem;">
              <div style="display: flex; justify-content: space-between; margin-bottom: 6px;">
                <span style="color: #64748b;">Clientes Ativos:</span>
                <strong style="color: #0f172a;">${pt.clientes}</strong>
              </div>
              <div style="display: flex; justify-content: space-between; margin-bottom: 6px;">
                <span style="color: #64748b;">Leads Mapeados:</span>
                <strong style="color: #1b4f99;">${pt.leads}</strong>
              </div>
              <div style="display: flex; justify-content: space-between; margin-bottom: 10px;">
                <span style="color: #64748b;">Viabilidade:</span>
                <span style="color: #059669; font-weight: 700;">${pt.viabilidade}</span>
              </div>
              <button type="button" class="btn btn-sm btn-dn-yellow w-100 fw-bold mb-2 shadow-sm" onclick="carregarEmpresasDoNodo('${escape(pt.bairro)}', ${pt.lat}, ${pt.lng})">
                <i class="bi bi-buildings-fill me-1"></i> Carregar Empresas do Nó
              </button>
              <a href="?bairro=${encodeURIComponent(pt.bairro)}" class="btn btn-sm btn-outline-primary w-100" style="padding: 4px 8px; font-size: 0.75rem;">
                <i class="bi bi-funnel me-1"></i> Filtrar Leads Deste Bairro
              </a>
            </div>
          </div>
        `;
        marker.bindPopup(popupContent);
        layerGroupFibra.addLayer(marker);

      } else if (pt.tipo === 'lead_oportunidade') {
        // Círculo térmico (Amarelo ou Vermelho conforme score)
        const isHighScore = pt.score >= 90;
        const heatColor = isHighScore ? '#ef4444' : '#f59e0b';
        const heatRadius = 220 + (pt.score * 1.5);

        const leadHeat = L.circle([pt.lat, pt.lng], {
          radius: heatRadius,
          color: heatColor,
          fillColor: heatColor,
          fillOpacity: isHighScore ? 0.28 : 0.20,
          weight: 1
        });
        layerGroupHeat.addLayer(leadHeat);

        // Marcador do Lead
        const pinClass = isHighScore ? 'custom-pin-lead high-score' : 'custom-pin-lead';
        const iconLead = L.divIcon({
          className: 'custom-pin-lead-wrapper',
          html: `<div class="${pinClass}" title="${pt.titulo}"><i class="bi bi-building"></i></div>`,
          iconSize: [28, 28],
          iconAnchor: [14, 14]
        });

        const marker = L.marker([pt.lat, pt.lng], { icon: iconLead });
        const popupContent = `
          <div style="width: 270px;">
            <div style="background: ${isHighScore ? 'linear-gradient(135deg, #b91c1c, #ef4444)' : 'linear-gradient(135deg, #d97706, #f59e0b)'}; color: white; padding: 10px 14px;">
              <div style="display: flex; justify-content: space-between; align-items: center;">
                <small style="color: white; opacity: 0.85; font-size: 0.7rem; font-weight: 600;">Oportunidade</small>
                <span style="background: rgba(0,0,0,0.25); color: white; padding: 2px 8px; border-radius: 12px; font-size: 0.7rem; font-weight: 700;">Score: ${pt.score}</span>
              </div>
              <h6 style="margin: 2px 0 0 0; font-weight: 700; font-size: 0.95rem; color: white;">${pt.titulo}</h6>
            </div>
            <div style="padding: 12px 14px; background: white; font-size: 0.85rem;">
              <div style="color: #475569; margin-bottom: 6px; font-size: 0.8rem;">
                <i class="bi bi-person me-1"></i> ${pt.contato} ${pt.cargo ? '&bull; ' + pt.cargo : ''}
              </div>
              <div style="color: #64748b; margin-bottom: 8px; font-size: 0.75rem;">
                <i class="bi bi-geo-alt me-1 text-danger"></i> ${pt.endereco}
              </div>
              <div style="background: #f8fafc; border: 1px solid #e2e8f0; border-radius: 6px; padding: 6px 10px; margin-bottom: 10px;">
                <div style="color: #1b4f99; font-weight: 700; font-size: 0.8rem;">${pt.plano}</div>
                <small style="color: #64748b;">${pt.valor} &bull; Operadora atual: <strong>${pt.operadora}</strong></small>
              </div>
              <div style="display: flex; gap: 6px;">
                ${pt.whatsapp_url !== '#' ? `
                  <a href="${pt.whatsapp_url}" target="_blank" class="btn btn-sm btn-success" style="flex: 1; font-size: 0.75rem; padding: 5px;">
                    <i class="bi bi-whatsapp me-1"></i> WhatsApp
                  </a>
                ` : ''}
                <a href="${pt.detail_url}" class="btn btn-sm btn-dn-blue" style="flex: 1; font-size: 0.75rem; padding: 5px;">
                  <i class="bi bi-eye me-1"></i> Dossiê
                </a>
              </div>
            </div>
          </div>
        `;
        marker.bindPopup(popupContent);
        layerGroupLeads.addLayer(marker);
      }
    });
  }

  function filtrarMapa(tipo) {
    document.querySelectorAll('.btn-group .btn').forEach(b => b.classList.remove('active'));
    
    if (tipo === 'todos') {
      document.getElementById('btnFiltroTodos').classList.add('active');
      if (!mapInstance.hasLayer(layerGroupFibra)) mapInstance.addLayer(layerGroupFibra);
      if (!mapInstance.hasLayer(layerGroupLeads)) mapInstance.addLayer(layerGroupLeads);
      if (!mapInstance.hasLayer(layerGroupHeat)) mapInstance.addLayer(layerGroupHeat);
    } else if (tipo === 'fibra') {
      document.getElementById('btnFiltroFibra').classList.add('active');
      if (!mapInstance.hasLayer(layerGroupFibra)) mapInstance.addLayer(layerGroupFibra);
      if (mapInstance.hasLayer(layerGroupLeads)) mapInstance.removeLayer(layerGroupLeads);
    } else if (tipo === 'leads') {
      document.getElementById('btnFiltroLeads').classList.add('active');
      if (mapInstance.hasLayer(layerGroupFibra)) mapInstance.removeLayer(layerGroupFibra);
      if (!mapInstance.hasLayer(layerGroupLeads)) mapInstance.addLayer(layerGroupLeads);
    }
  }

  function centralizarCampoGrande() {
    if (mapInstance) {
      mapInstance.setView(centroCG, 13);
    }
  }

  // =========================================================================
  // CAMADA BASE: MAPBOX (STREETS / SATELLITE) OU OPENSTREETMAP (SEM WATERMARK)
  // =========================================================================
  function definirCamadaBase(estilo) {
    if (!mapInstance) return;

    if (currentBaseLayer) {
      mapInstance.removeLayer(currentBaseLayer);
    }

    const hasMapbox = Boolean(mapboxApiKey && mapboxApiKey.trim().length > 5);

    if (hasMapbox && estilo === 'satelite') {
      currentBaseLayer = L.tileLayer('https://api.mapbox.com/styles/v1/mapbox/satellite-streets-v12/tiles/{z}/{x}/{y}?access_token=' + encodeURIComponent(mapboxApiKey.trim()), {
        attribution: '&copy; <a href="https://www.mapbox.com/">Mapbox</a> &copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> &copy; Maxar',
        tileSize: 512,
        zoomOffset: -1,
        maxZoom: 19
      });
    } else if (hasMapbox && estilo === 'ruas') {
      currentBaseLayer = L.tileLayer('https://api.mapbox.com/styles/v1/mapbox/streets-v12/tiles/{z}/{x}/{y}?access_token=' + encodeURIComponent(mapboxApiKey.trim()), {
        attribution: '&copy; <a href="https://www.mapbox.com/">Mapbox</a> &copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a>',
        tileSize: 512,
        zoomOffset: -1,
        maxZoom: 19
      });
      currentBaseLayer.on('tileerror', function() {
        if (!window._mapboxFallbackTriggered) {
          window._mapboxFallbackTriggered = true;
          console.warn('Falha no carregamento dos tiles do Mapbox. Alternando automaticamente para OpenStreetMap.');
          definirCamadaBase('osm');
        }
      });
    } else {
      // OpenStreetMap padrão: 100% gratuito, sem exigência de API Key e sem marca d'água
      currentBaseLayer = L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png', {
        attribution: '&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors',
        maxZoom: 19
      });
    }

    currentBaseLayer.addTo(mapInstance);
  }

  // =========================================================================
  // CAMADAS GEOJSON DINÂMICAS (BAIRROS, MACROZONAS E PARCELAMENTOS)
  // =========================================================================
  const geojsonLayers = {
    bairros: { layer: null, data: null, url: '/leads/api/geojson/bairros' },
    macrozonas: { layer: null, data: null, url: '/leads/api/geojson/macrozonas' },
    parcelamentos: { layer: null, data: null, url: '/leads/api/geojson/parcelamentos' }
  };

  async function toggleCamadaGeo(tipo, ativo) {
    const item = geojsonLayers[tipo];
    if (!item || !mapInstance) return;

    const spinner = document.getElementById('geoLoadingSpinner');

    if (ativo) {
      if (!item.data) {
        if (spinner) spinner.classList.remove('d-none');
        try {
          const resp = await fetch(item.url);
          if (!resp.ok) throw new Error('Falha ao baixar camada ' + tipo);
          item.data = await resp.json();

          if (tipo === 'bairros') {
            item.layer = L.geoJSON(item.data, {
              pane: 'geojsonPane',
              style: function(feature) {
                return {
                  color: '#1b4f99',
                  weight: 1.5,
                  opacity: 0.85,
                  fillColor: '#3b82f6',
                  fillOpacity: 0.08
                };
              },
              onEachFeature: function(feature, layer) {
                const props = feature.properties || {};
                const nomeBairro = props.bairro || 'Bairro';
                const regiao = props.regiao_urb || '';
                layer.bindTooltip(`<strong>${nomeBairro}</strong>${regiao ? `<br><small class="text-muted">Região: ${regiao}</small>` : ''}`, { sticky: true });
                layer.on({
                  mouseover: function() {
                    layer.setStyle({ weight: 2.5, fillOpacity: 0.22, color: '#0f2d57' });
                  },
                  mouseout: function() {
                    if (item.layer) item.layer.resetStyle(layer);
                  },
                  click: function(e) {
                    L.DomEvent.stopPropagation(e);
                    const popupContent = `
                      <div style="padding: 10px; font-family: 'Plus Jakarta Sans', sans-serif;">
                        <span class="badge py-1 px-2 rounded-pill mb-1" style="background: #e0f2fe; color: #0369a1; font-size: 0.7rem; font-weight: 700;">
                          Bairro Oficial &bull; Campo Grande
                        </span>
                        <div style="font-weight: 700; color: #0f2d57; font-size: 1rem; margin-top: 2px;">${nomeBairro}</div>
                        <div style="font-size: 0.75rem; color: #64748b; margin-bottom: 8px;">Região Urbana: <strong>${regiao || 'Campo Grande'}</strong></div>
                        <a href="?bairro=${encodeURIComponent(nomeBairro)}" class="btn btn-sm btn-dn-blue w-100" style="font-size: 0.75rem; padding: 4px 8px;">
                          <i class="bi bi-funnel me-1"></i> Filtrar Leads Deste Bairro
                        </a>
                      </div>
                    `;
                    layer.bindPopup(popupContent).openPopup();
                  }
                });
              }
            });
          } else if (tipo === 'macrozonas') {
            const colorsMZ = ['#2563eb', '#7c3aed', '#059669', '#d97706', '#dc2626', '#0891b2', '#4b5563'];
            item.layer = L.geoJSON(item.data, {
              pane: 'geojsonPane',
              style: function(feature) {
                const id = feature.properties ? (feature.properties.id || 1) : 1;
                const cor = colorsMZ[id % colorsMZ.length];
                return {
                  color: cor,
                  weight: 1.5,
                  opacity: 0.85,
                  fillColor: cor,
                  fillOpacity: 0.10,
                  dashArray: '4, 4'
                };
              },
              onEachFeature: function(feature, layer) {
                const props = feature.properties || {};
                const nome = props.nome || 'Macrozona';
                const leg = props.legislacao || 'Plano Diretor 2018';
                layer.bindTooltip(`<strong>${nome}</strong><br><small class="text-muted">${props.bairro || ''}</small>`, { sticky: true });
                layer.bindPopup(`
                  <div style="padding: 10px; font-family: 'Plus Jakarta Sans', sans-serif;">
                    <span class="badge bg-primary mb-1" style="font-size: 0.7rem;">Macrozoneamento Urbano</span>
                    <h6 style="margin: 0; font-weight: 700; color: #0f2d57;">${nome}</h6>
                    <div style="font-size: 0.75rem; color: #64748b; margin-top: 4px;">${leg}</div>
                  </div>
                `);
              }
            });
          } else if (tipo === 'parcelamentos') {
            item.layer = L.geoJSON(item.data, {
              pane: 'geojsonPane',
              style: {
                color: '#d97706',
                weight: 1,
                opacity: 0.75,
                fillColor: '#f59e0b',
                fillOpacity: 0.06
              },
              onEachFeature: function(feature, layer) {
                const props = feature.properties || {};
                const nomeParc = props.nome_parcelamento || props.nome_exibicao || 'Parcelamento';
                const ano = props.ano_referencia || '';
                layer.bindTooltip(`<strong>${nomeParc}</strong>${ano ? ` (${ano})` : ''}`, { sticky: true });
              }
            });
          }
        } catch (err) {
          console.error('Erro ao carregar GeoJSON:', err);
          alert('Não foi possível carregar a camada ' + tipo + '.');
          const chk = document.getElementById('checkGeo' + tipo.charAt(0).toUpperCase() + tipo.slice(1));
          if (chk) chk.checked = false;
          return;
        } finally {
          if (spinner) spinner.classList.add('d-none');
        }
      }

      if (item.layer && !mapInstance.hasLayer(item.layer)) {
        mapInstance.addLayer(item.layer);
      }
    } else {
      if (item.layer && mapInstance.hasLayer(item.layer)) {
        mapInstance.removeLayer(item.layer);
      }
    }

    atualizarBadgeCamadas();
  }

  function atualizarBadgeCamadas() {
    let ativas = 0;
    ['bairros', 'macrozonas', 'parcelamentos'].forEach(t => {
      if (geojsonLayers[t].layer && mapInstance && mapInstance.hasLayer(geojsonLayers[t].layer)) {
        ativas++;
      }
    });
    const badge = document.getElementById('badgeCamadasAtivas');
    if (badge) {
      if (ativas > 0) {
        badge.textContent = ativas;
        badge.classList.remove('d-none');
      } else {
        badge.classList.add('d-none');
      }
    }
  }

  // =========================================================================
  // MODO TELA CHEIA (FULLSCREEN) DO MAPA
  // =========================================================================
  function toggleFullscreenMapa() {
    const card = document.getElementById('cardMapaCalor');
    const icon = document.getElementById('iconFullscreenMap');
    const label = document.getElementById('labelFullscreenMap');
    if (!card) return;

    const isCurrentlyFullscreen = card.classList.contains('map-card-fullscreen');
    if (!isCurrentlyFullscreen) {
      card.classList.add('map-card-fullscreen');
      if (icon) {
        icon.classList.remove('bi-arrows-fullscreen');
        icon.classList.add('bi-fullscreen-exit');
      }
      if (label) label.textContent = 'Sair da Tela Cheia';

      // Tenta acionar HTML5 Fullscreen API se disponível e permitido
      if (card.requestFullscreen && !document.fullscreenElement) {
        card.requestFullscreen().catch(() => {});
      }
    } else {
      card.classList.remove('map-card-fullscreen');
      if (icon) {
        icon.classList.remove('bi-fullscreen-exit');
        icon.classList.add('bi-arrows-fullscreen');
      }
      if (label) label.textContent = 'Tela Cheia';

      if (document.fullscreenElement && document.exitFullscreen) {
        document.exitFullscreen().catch(() => {});
      }
    }

    // Invalida tamanho do Leaflet para atualizar tiles instantaneamente
    if (mapInstance) {
      setTimeout(() => mapInstance.invalidateSize(), 100);
      setTimeout(() => mapInstance.invalidateSize(), 320);
    }
  }

  // Escuta alteração nativa de Fullscreen (ex: usuário apertou ESC ou F11)
  document.addEventListener('fullscreenchange', function() {
    const card = document.getElementById('cardMapaCalor');
    if (!document.fullscreenElement && card && card.classList.contains('map-card-fullscreen')) {
      card.classList.remove('map-card-fullscreen');
      const icon = document.getElementById('iconFullscreenMap');
      const label = document.getElementById('labelFullscreenMap');
      if (icon) {
        icon.classList.remove('bi-fullscreen-exit');
        icon.classList.add('bi-arrows-fullscreen');
      }
      if (label) label.textContent = 'Tela Cheia';
      if (mapInstance) {
        setTimeout(() => mapInstance.invalidateSize(), 100);
        setTimeout(() => mapInstance.invalidateSize(), 300);
      }
    }
  });

  // Escuta tecla ESC para sair do modo tela cheia CSS
  document.addEventListener('keydown', function(e) {
    if (e.key === 'Escape') {
      const card = document.getElementById('cardMapaCalor');
      if (card && card.classList.contains('map-card-fullscreen')) {
        toggleFullscreenMapa();
      }
    }
  });

  // =========================================================================
  // HOOK DE INTEGRAÇÃO & CARREGAMENTO DINÂMICO: NÓ DE FIBRA DIGITALNET
  // =========================================================================
  window.carregarEmpresasDoNodo = async function(bairroEscaped, lat, lng) {
    const bairro = unescape(bairroEscaped);
    console.log(`[DigitalNet] Carregando empresas do Nó Óptico: ${bairro} (${lat}, ${lng})`);

    // 1. Dispara evento customizado da DigitalNet
    const event = new CustomEvent('digitalnet:nodo_fibra_clicado', {
      detail: { bairro: bairro, lat: lat, lng: lng }
    });
    window.dispatchEvent(event);

    // 2. Elementos da interface Offcanvas
    const offcanvasEl = document.getElementById('offcanvasNodoEmpresas');
    const labelEl = document.getElementById('offcanvasNodoLabel');
    const subEl = document.getElementById('offcanvasNodoSub');
    const loadingEl = document.getElementById('offcanvasLoading');
    const conteudoEl = document.getElementById('offcanvasConteudo');
    const listaEl = document.getElementById('offcanvasListaEmpresas');
    const totalEl = document.getElementById('offcanvasTotalEmpresas');
    const linkFiltrarEl = document.getElementById('offcanvasLinkFiltrarBairro');

    if (labelEl) labelEl.textContent = `Nó Óptico: ${bairro}`;
    if (subEl) subEl.innerHTML = `Raio de Cobertura de Fibra &bull; Campo Grande - MS`;
    if (linkFiltrarEl) linkFiltrarEl.href = `?bairro=${encodeURIComponent(bairro)}`;
    if (loadingEl) loadingEl.classList.remove('d-none');
    if (conteudoEl) conteudoEl.classList.add('d-none');
    if (listaEl) listaEl.innerHTML = '';

    // Abre a gaveta lateral (Offcanvas)
    if (offcanvasEl) {
      const bsOffcanvas = bootstrap.Offcanvas.getOrCreateInstance(offcanvasEl);
      bsOffcanvas.show();
    }

    // 3. Centraliza a visualização do mapa nas coordenadas do Nó
    if (mapInstance && lat && lng) {
      mapInstance.flyTo([lat, lng], 15, { animate: true, duration: 1.0 });
    }

    mostrarNotificacaoNodo(`Varrendo empresas no raio do Nó [${bairro}]...`);

    try {
      const url = `/leads/api/nodo/${encodeURIComponent(bairro)}/empresas?lat=${lat || ''}&lng=${lng || ''}&limite=8`;
      const resp = await fetch(url);
      if (!resp.ok) throw new Error(`Falha HTTP ${resp.status}`);
      const data = await resp.json();

      if (!data.success || !Array.isArray(data.empresas)) {
        throw new Error(data.error || 'Resposta inválida do servidor');
      }

      const empresas = data.empresas;
      if (totalEl) {
        totalEl.innerHTML = `<strong>${empresas.length}</strong> empresas identificadas no poste`;
      }

      // 4. Desenha círculo de abrangência e marcadores no mapa
      if (layerGroupNodoEmpresas) {
        layerGroupNodoEmpresas.clearLayers();

        if (lat && lng) {
          const circleCobertura = L.circle([lat, lng], {
            radius: 420,
            color: '#fbbf24',
            fillColor: '#fbbf24',
            fillOpacity: 0.14,
            weight: 2,
            dashArray: '5, 5'
          });
          layerGroupNodoEmpresas.addLayer(circleCobertura);
        }

        empresas.forEach((emp, index) => {
          const isHighScore = emp.lead_score >= 90;
          const pinHtml = `
            <div class="custom-pin-lead ${isHighScore ? 'high-score' : ''}" style="border: 2px solid #fbbf24; transform: scale(1.12); box-shadow: 0 0 10px rgba(251, 191, 36, 0.75);">
              <i class="bi bi-buildings"></i>
            </div>
          `;
          const icon = L.divIcon({
            className: 'custom-pin-nodo-empresa',
            html: pinHtml,
            iconSize: [30, 30],
            iconAnchor: [15, 15]
          });

          const marker = L.marker([emp.lat, emp.lng], { icon: icon });
          const popupHtml = `
            <div style="width: 270px; font-family: 'Plus Jakarta Sans', sans-serif;">
              <div style="background: linear-gradient(135deg, #0f2d57, #1b4f99); color: white; padding: 10px 14px;">
                <div style="display: flex; justify-content: space-between; align-items: center;">
                  <span class="badge" style="background: #fbbf24; color: #0f172a; font-weight: 700; font-size: 0.65rem;">
                    ${emp.distancia_estimada_m ? `${emp.distancia_estimada_m}m do Nó` : 'No Raio da Fibra'}
                  </span>
                  <span class="badge bg-danger" style="font-size: 0.7rem;">${emp.lead_score} pts</span>
                </div>
                <h6 style="margin: 4px 0 0 0; font-weight: 700; color: white;">${emp.empresa}</h6>
              </div>
              <div style="padding: 12px 14px; background: white; font-size: 0.82rem;">
                <div class="text-muted mb-1"><i class="bi bi-person me-1"></i>${emp.nome} &bull; <span class="text-secondary">${emp.cargo}</span></div>
                <div class="text-muted mb-2"><i class="bi bi-geo-alt me-1 text-danger"></i>${emp.logradouro}, ${emp.numero}</div>
                <div class="p-2 rounded mb-2" style="background: #f8fafc; border: 1px solid #e2e8f0;">
                  <div class="fw-bold" style="color: #1b4f99;">${emp.plano_sugerido}</div>
                  <small class="text-muted">R$ ${emp.valor_mensal_sugerido.toFixed(2).replace('.', ',')}/mês &bull; Operadora: <strong>${emp.operadora_atual}</strong></small>
                </div>
                <div class="d-flex gap-2">
                  ${emp.whatsapp_url && emp.whatsapp_url !== '#' ? `
                    <a href="${emp.whatsapp_url}" target="_blank" class="btn btn-sm btn-success flex-fill" style="font-size: 0.75rem; padding: 5px;">
                      <i class="bi bi-whatsapp me-1"></i> WhatsApp
                    </a>
                  ` : ''}
                  <a href="${emp.detail_url}" class="btn btn-sm btn-dn-blue flex-fill" style="font-size: 0.75rem; padding: 5px;">
                    <i class="bi bi-eye me-1"></i> Dossiê
                  </a>
                </div>
              </div>
            </div>
          `;
          marker.bindPopup(popupHtml);
          layerGroupNodoEmpresas.addLayer(marker);

          emp._leafletMarker = marker;
        });
      }

      // 5. Renderiza os cards na gaveta lateral (Offcanvas)
      if (listaEl) {
        listaEl.innerHTML = empresas.map((emp, i) => `
          <div class="card border border-light-subtle shadow-sm rounded-3 p-3 bg-white" style="transition: all 0.2s ease;">
            <div class="d-flex justify-content-between align-items-start mb-2">
              <div>
                <h6 class="fw-bold mb-1 text-dark" style="font-size: 0.95rem;">${emp.empresa}</h6>
                <div class="small text-muted"><i class="bi bi-person-circle me-1 text-primary"></i>${emp.nome} (${emp.cargo})</div>
              </div>
              <span class="badge ${emp.lead_score >= 90 ? 'bg-danger' : 'bg-primary'} px-2 py-1" style="font-size: 0.75rem;">
                ${emp.lead_score} pts
              </span>
            </div>

            <div class="small text-muted mb-2">
              <i class="bi bi-geo-alt-fill text-danger me-1"></i>${emp.logradouro}, ${emp.numero}
              <span class="badge bg-light text-dark border ms-1">${emp.distancia_estimada_m ? `${emp.distancia_estimada_m}m do Nó` : 'Fibra Ativa'}</span>
            </div>

            <div class="p-2 rounded-2 mb-2" style="background: #eff6ff; border: 1px solid #bfdbfe;">
              <div class="d-flex justify-content-between align-items-center mb-1">
                <strong style="color: #1b4f99; font-size: 0.8rem;">${emp.plano_sugerido}</strong>
                <span class="text-dark fw-bold" style="font-size: 0.8rem;">R$ ${emp.valor_mensal_sugerido.toFixed(2).replace('.', ',')}</span>
              </div>
              <div class="text-muted" style="font-size: 0.72rem;">
                Operadora Atual: <strong class="text-dark">${emp.operadora_atual}</strong> &bull; Dor: ${emp.dor_principal}
              </div>
            </div>

            <div class="d-flex align-items-center gap-2 pt-1 border-top">
              ${emp.whatsapp_url && emp.whatsapp_url !== '#' ? `
                <a href="${emp.whatsapp_url}" target="_blank" class="btn btn-sm btn-success flex-fill" style="font-size: 0.75rem; padding: 5px 8px;">
                  <i class="bi bi-whatsapp me-1"></i> WhatsApp Anti-Ban
                </a>
              ` : ''}
              <a href="${emp.detail_url}" class="btn btn-sm btn-outline-secondary" style="font-size: 0.75rem; padding: 5px 8px;" title="Ver Dossiê Completo">
                <i class="bi bi-file-earmark-person"></i>
              </a>
              <button type="button" class="btn btn-sm btn-light border" style="font-size: 0.75rem; padding: 5px 8px;" onclick="focarEmpresaNoMapa(${i})" title="Localizar no Mapa">
                <i class="bi bi-crosshair"></i>
              </button>
            </div>
          </div>
        `).join('');
      }

      window._nodoEmpresasAtuais = empresas;

      if (loadingEl) loadingEl.classList.add('d-none');
      if (conteudoEl) conteudoEl.classList.remove('d-none');

      mostrarNotificacaoNodo(`${empresas.length} empresas carregadas no Nó [${bairro}]!`);

    } catch (err) {
      console.error('Erro ao carregar empresas do nó:', err);
      if (loadingEl) loadingEl.classList.add('d-none');
      if (conteudoEl) conteudoEl.classList.remove('d-none');
      if (listaEl) {
        listaEl.innerHTML = `
          <div class="alert alert-danger small mb-0">
            <i class="bi bi-exclamation-triangle-fill me-1"></i> Não foi possível carregar as empresas do nó no momento. Tente novamente.
          </div>
        `;
      }
      mostrarNotificacaoNodo(`Erro ao buscar empresas para o bairro ${bairro}.`);
    }
  };

  window.focarEmpresaNoMapa = function(index) {
    if (!window._nodoEmpresasAtuais || !window._nodoEmpresasAtuais[index]) return;
    const emp = window._nodoEmpresasAtuais[index];
    if (mapInstance && emp.lat && emp.lng) {
      mapInstance.flyTo([emp.lat, emp.lng], 16.5, { animate: true, duration: 0.8 });
      if (emp._leafletMarker) {
        setTimeout(() => emp._leafletMarker.openPopup(), 850);
      }
    }
  };

  function mostrarNotificacaoNodo(mensagem) {
    let toast = document.getElementById('dnNodoToast');
    if (!toast) {
      toast = document.createElement('div');
      toast.id = 'dnNodoToast';
      toast.style.cssText = 'position: fixed; bottom: 24px; right: 24px; z-index: 2000; background: linear-gradient(135deg, #0f2d57, #1b4f99); color: white; padding: 12px 18px; border-radius: 10px; box-shadow: 0 10px 25px rgba(0,0,0,0.3); font-size: 0.875rem; display: flex; align-items: center; gap: 10px; border: 1px solid rgba(251, 191, 36, 0.4); transition: opacity 0.3s ease;';
      document.body.appendChild(toast);
    }
    toast.innerHTML = `<i class="bi bi-broadcast text-warning fs-5"></i> <div><strong>Nó DigitalNet</strong><div style="font-size: 0.78rem; opacity: 0.9;">${mensagem}</div></div>`;
    toast.style.opacity = '1';
    toast.style.display = 'flex';
    clearTimeout(window._nodoToastTimer);
    window._nodoToastTimer = setTimeout(() => {
      toast.style.opacity = '0';
      setTimeout(() => toast.style.display = 'none', 300);
    }, 4500);
  }

  // Inicializa quando a página carregar
  document.addEventListener('DOMContentLoaded', function() {
    initMap();
  });


  // =========================================================================
  // DATATABLES RESPONSIVE E LINHAS ANINHADAS (ESTILO RESULTADO_TABLE.JS)
  // =========================================================================
