# --- app/utils/auth_decorators.py ---
cat > 'app/utils/auth_decorators.py' <<'OMNI_EOF'
from functools import wraps
from flask import abort, flash, redirect, url_for, request
from flask_login import current_user
from app.models.user import PERFIL_ADMIN, PERFIL_LIDER, PERFIL_AGENTE


def admin_required(f):
    """
    Exige que o usuário esteja autenticado e tenha o perfil ou grupo de Administrador.
    """
    @wraps(f)
    def decorated_function(*args, **kwargs):
        if not current_user.is_authenticated:
            flash('Por favor, faça login para acessar esta página.', 'warning')
            return redirect(url_for('auth.login', next=request.url))
        if not current_user.is_admin:
            flash('Acesso negado. Esta funcionalidade é restrita a Administradores.', 'danger')
            abort(403)
        return f(*args, **kwargs)
    return decorated_function


def lider_required(f):
    """
    Exige que o usuário seja Líder Técnico ou Administrador.
    """
    @wraps(f)
    def decorated_function(*args, **kwargs):
        if not current_user.is_authenticated:
            flash('Por favor, faça login para acessar esta página.', 'warning')
            return redirect(url_for('auth.login', next=request.url))
        if not current_user.is_lider_tecnico:
            flash('Acesso negado. Apenas Líderes Técnicos e Administradores possuem esta permissão.', 'danger')
            abort(403)
        return f(*args, **kwargs)
    return decorated_function


def perfil_required(*perfis):
    """
    Exige que o usuário pertença a um dos perfis fornecidos.
    """
    def decorator(f):
        @wraps(f)
        def decorated_function(*args, **kwargs):
            if not current_user.is_authenticated:
                flash('Por favor, faça login para acessar esta página.', 'warning')
                return redirect(url_for('auth.login', next=request.url))
            if not current_user.has_perfil(*perfis):
                flash('Acesso negado para o seu perfil de usuário.', 'danger')
                abort(403)
            return f(*args, **kwargs)
        return decorated_function
    return decorator
OMNI_EOF

# --- app/utils/filters.py ---
cat > 'app/utils/filters.py' <<'OMNI_EOF'
def format_currency(value):
    """Formats float/decimal into Brazilian Real (R$ X.XXX,XX)."""
    if value is None:
        return "R$ 0,00"
    try:
        val = float(value)
        return f"R$ {val:,.2f}".replace(',', 'X').replace('.', ',').replace('X', '.')
    except (ValueError, TypeError):
        return str(value)


def format_date(value, fmt='%d/%m/%Y %H:%M'):
    """Formats datetime object to standard Brazilian date format."""
    if not value:
        return "-"
    try:
        return value.strftime(fmt)
    except Exception:
        return str(value)


def format_date_short(value):
    """Formats datetime object to short DD/MM/YYYY."""
    return format_date(value, fmt='%d/%m/%Y')


def format_document(doc):
    """Formats CPF (11 digits) or CNPJ (14 digits) if digits only."""
    if not doc:
        return "-"
    digits = ''.join(filter(str.isdigit, str(doc)))
    if len(digits) == 11:
        return f"{digits[:3]}.{digits[3:6]}.{digits[6:9]}-{digits[9:]}"
    elif len(digits) == 14:
        return f"{digits[:2]}.{digits[2:5]}.{digits[5:8]}/{digits[8:12]}-{digits[12:]}"
    return doc


def format_phone(phone):
    """Formats Brazilian phone numbers."""
    if not phone:
        return "-"
    digits = ''.join(filter(str.isdigit, str(phone)))
    if len(digits) == 11:
        return f"({digits[:2]}) {digits[2:7]}-{digits[7:]}"
    elif len(digits) == 10:
        return f"({digits[:2]}) {digits[2:6]}-{digits[6:]}"
    return phone


def init_filters(app):
    app.jinja_env.filters['currency'] = format_currency
    app.jinja_env.filters['datetime_br'] = format_date
    app.jinja_env.filters['date_br'] = format_date_short
    app.jinja_env.filters['doc_br'] = format_document
    app.jinja_env.filters['phone_br'] = format_phone
OMNI_EOF

