cat > 'scripts/analisar_geojson_postgis.py' <<'OMNI_EOF'
#!/usr/bin/env python3
"""
Script de Análise Estrutural de Arquivos GeoJSON e Criação de Tabelas PostGIS.

Lê e analisa os arquivos .geojson do diretório geojson/, infere os tipos
corretos de cada coluna (INTEGER, BIGINT, NUMERIC, VARCHAR, TIMESTAMPTZ, DATE,
BOOLEAN, TEXT e GEOMETRY PostGIS), gera DDL com índices espaciais (GIST) e
permite criar as tabelas e importar os dados diretamente no PostgreSQL + PostGIS.

Uso:
    # Apenas analisar e exibir o relatório de tipos no terminal:
    python scripts/analisar_geojson_postgis.py

    # Gerar arquivo SQL DDL:
    python scripts/analisar_geojson_postgis.py --output-sql schema_geo.sql

    # Executar DDL e criar as tabelas no PostgreSQL (localhost / db_geo):
    python scripts/analisar_geojson_postgis.py --execute

    # Criar tabelas E importar todos os dados dos arquivos GeoJSON:
    python scripts/analisar_geojson_postgis.py --execute --import-data

Parâmetros adicionais:
    --dbname db_geo       (padrão: db_geo ou $PGDATABASE)
    --host localhost      (padrão: localhost ou $PGHOST)
    --port 5432           (padrão: 5432 ou $PGPORT)
    --user postgres       (padrão: postgres ou $PGUSER)
    --schema public       (padrão: public)
    --table-prefix geo_   (padrão: geo_)
    --srid 4326           (padrão: 4326 - WGS84)
"""

import argparse
import glob
import json
import os
import re
import subprocess
import sys
import tempfile
import time
from datetime import datetime
from pathlib import Path
from typing import Any, Dict, List, Optional, Set, Tuple


# ==============================================================================
# 1. INFERÊNCIA DE TIPOS E ANÁLISE ESTRUTURAL
# ==============================================================================

ISO_DATE_REGEX = re.compile(r'^\d{4}-\d{2}-\d{2}(?:Z|[+-]\d{2}:?\d{2})?$')
ISO_DATETIME_REGEX = re.compile(r'^\d{4}-\d{2}-\d{2}[T\s]\d{2}:\d{2}:\d{2}(?:\.\d+)?(?:Z|[+-]\d{2}:?\d{2})?$')


class FieldStats:
    """Acumula estatísticas e tipos observados em uma propriedade GeoJSON."""

    def __init__(self, name: str):
        self.name = name
        self.observed_types: Set[str] = set()
        self.total_count = 0
        self.null_count = 0
        self.min_val: Any = None
        self.max_val: Any = None
        self.max_str_len = 0
        self.distinct_samples: Set[Any] = set()

    def record_value(self, val: Any) -> None:
        self.total_count += 1
        if val is None:
            self.null_count += 1
            return

        if len(self.distinct_samples) < 5:
            self.distinct_samples.add(str(val)[:40])

        if isinstance(val, bool):
            self.observed_types.add('bool')
        elif isinstance(val, int):
            self.observed_types.add('int')
            self._update_min_max(val)
        elif isinstance(val, float):
            self.observed_types.add('float')
            self._update_min_max(val)
        elif isinstance(val, str):
            clean = val.strip()
            self.max_str_len = max(self.max_str_len, len(clean))
            if ISO_DATETIME_REGEX.match(clean):
                self.observed_types.add('timestamptz')
            elif ISO_DATE_REGEX.match(clean):
                self.observed_types.add('date')
            else:
                self.observed_types.add('str')
        elif isinstance(val, (dict, list)):
            self.observed_types.add('json')
        else:
            self.observed_types.add('str')
            self.max_str_len = max(self.max_str_len, len(str(val)))

    def _update_min_max(self, val: Any) -> None:
        if self.min_val is None or val < self.min_val:
            self.min_val = val
        if self.max_val is None or val > self.max_val:
            self.max_val = val

    def infer_postgres_type(self) -> str:
        """Determina o tipo ideal de dado do PostgreSQL baseado nos valores reais."""
        types = self.observed_types - {'null'}
        if not types:
            # Coluna 100% nula na amostra (ex: codigo_ibge)
            if any(term in self.name.lower() for term in ('id', 'cod', 'codigo', 'cod_')):
                return 'VARCHAR(50)'
            return 'TEXT'

        # Se houver bool e nada mais
        if types == {'bool'}:
            return 'BOOLEAN'

        # Numéricos
        if types == {'int'}:
            if self.min_val is not None and self.max_val is not None:
                if -2147483648 <= self.min_val and self.max_val <= 2147483647:
                    return 'INTEGER'
                return 'BIGINT'
            return 'INTEGER'

        if types in ({'float'}, {'int', 'float'}):
            # Se parecer área ou valor monetário, usa NUMERIC(14, 2)
            if any(term in self.name.lower() for term in ('area', 'valor', 'preco', 'taxa')):
                return 'NUMERIC(14, 2)'
            return 'DOUBLE PRECISION'

        # Datas
        if types == {'date'}:
            return 'DATE'
        if types == {'timestamptz'}:
            return 'TIMESTAMPTZ'
        if types == {'date', 'timestamptz'}:
            return 'TIMESTAMPTZ'

        # JSONB
        if 'json' in types:
            return 'JSONB'

        # Strings / Textos
        mlen = self.max_str_len
        if mlen == 0:
            return 'VARCHAR(50)'
        elif mlen <= 5:
            return 'VARCHAR(10)'
        elif mlen <= 15:
            return 'VARCHAR(25)'
        elif mlen <= 35:
            return 'VARCHAR(50)'
        elif mlen <= 80:
            return 'VARCHAR(120)'
        elif mlen <= 160:
            return 'VARCHAR(255)'
        else:
            return 'TEXT'


class TableSchema:
    """Metadados de uma tabela gerada a partir de um GeoJSON."""

    def __init__(self, filepath: str, table_name: str, srid: int = 4326):
        self.filepath = filepath
        self.filename = os.path.basename(filepath)
        self.table_name = table_name
        self.srid = srid
        self.feature_count = 0
        self.geometry_type = 'MultiPolygon'
        self.fields: Dict[str, FieldStats] = {}
        self.pk_field: Optional[str] = None
        self.has_geom = False
        self.bbox: Optional[Tuple[float, float, float, float]] = None

    def analyze(self) -> None:
        """Lê o GeoJSON e compila todas as propriedades e geometrias."""
        with open(self.filepath, 'r', encoding='utf-8') as fp:
            data = json.load(fp)

        features = data.get('features', [])
        self.feature_count = len(features)
        geom_types: Set[str] = set()

        min_x = min_y = float('inf')
        max_x = max_y = float('-inf')

        for feat in features:
            geom = feat.get('geometry')
            if geom:
                self.has_geom = True
                g_type = geom.get('type')
                if g_type:
                    geom_types.add(g_type)

            props = feat.get('properties') or {}
            for k, v in props.items():
                sanitized_name = re.sub(r'[^a-zA-Z0-9_]', '_', k.strip().lower())
                if sanitized_name not in self.fields:
                    self.fields[sanitized_name] = FieldStats(sanitized_name)
                self.fields[sanitized_name].record_value(v)

        # Determina tipo geométrico padrão
        if 'MultiPolygon' in geom_types or 'Polygon' in geom_types:
            self.geometry_type = 'MultiPolygon'
        elif 'Point' in geom_types or 'MultiPoint' in geom_types:
            self.geometry_type = 'Point' if geom_types == {'Point'} else 'MultiPoint'
        elif 'LineString' in geom_types or 'MultiLineString' in geom_types:
            self.geometry_type = 'MultiLineString'
        elif geom_types:
            self.geometry_type = list(geom_types)[0]
        else:
            self.geometry_type = 'Geometry'

        # Identifica candidato a chave primária
        for candidate in ('gid', 'id', 'codigo', 'codimo'):
            if candidate in self.fields:
                st = self.fields[candidate]
                if st.null_count == 0 and 'int' in st.observed_types:
                    self.pk_field = candidate
                    break

    def generate_ddl(self, schema: str = 'public', drop_existing: bool = False) -> str:
        """Gera o comando DDL SQL para criação da tabela e índices."""
        full_table = f'"{schema}"."{self.table_name}"'
        lines: List[str] = []

        if drop_existing:
            lines.append(f"DROP TABLE IF EXISTS {full_table} CASCADE;\n")

        lines.append(f"-- ============================================================================")
        lines.append(f"-- Tabela: {self.table_name}")
        lines.append(f"-- Origem: {self.filename} ({self.feature_count} features)")
        lines.append(f"-- Geometria: {self.geometry_type} (SRID {self.srid})")
        lines.append(f"-- ============================================================================")
        lines.append(f"CREATE TABLE IF NOT EXISTS {full_table} (")

        col_defs: List[str] = []

        # Se não houver campo PK inteiro, cria id_seq autoincremental
        if not self.pk_field:
            col_defs.append('    "id" SERIAL PRIMARY KEY')

        for col_name, st in self.fields.items():
            pg_type = st.infer_postgres_type()
            pk_clause = ' PRIMARY KEY' if col_name == self.pk_field else ''
            null_clause = '' if col_name == self.pk_field or st.null_count > 0 else ''
            col_defs.append(f'    "{col_name}" {pg_type}{pk_clause}{null_clause}')

        if self.has_geom:
            col_defs.append(f'    "geom" geometry({self.geometry_type}, {self.srid})')

        lines.append(',\n'.join(col_defs))
        lines.append(");")
        lines.append("")

        # Comentário na tabela
        lines.append(f"COMMENT ON TABLE {full_table} IS 'Importado do arquivo {self.filename} ({self.feature_count} feições geográficas).';")

        # Índices espaciais e B-Tree
        if self.has_geom:
            idx_name = f"idx_{self.table_name}_geom"
            lines.append(f"CREATE INDEX IF NOT EXISTS \"{idx_name}\" ON {full_table} USING GIST (\"geom\");")

        # Índices nas colunas de busca frequente
        common_search_cols = (
            'bairro', 'nomebairro', 'nome', 'nome_parcelamento', 'regiao_urb',
            'nomeregiao', 'codlote', 'inscant', 'codimo', 'ruaimo', 'cidade'
        )
        for c in common_search_cols:
            if c in self.fields and c != self.pk_field:
                idx_name = f"idx_{self.table_name}_{c}"
                lines.append(f"CREATE INDEX IF NOT EXISTS \"{idx_name}\" ON {full_table} (\"{c}\");")

        lines.append("")
        return '\n'.join(lines)


# ==============================================================================
# 2. INGESTÃO DE DADOS (IMPORTAÇÃO SQL NATIVA PARA POSTGIS)
# ==============================================================================

def escape_sql_val(val: Any, target_type: str) -> str:
    """Escapa e formata o valor para a instrução SQL INSERT."""
    if val is None:
        return 'NULL'
    if isinstance(val, bool):
        return 'TRUE' if val else 'FALSE'
    if isinstance(val, (int, float)):
        return str(val)
    if isinstance(val, (dict, list)):
        dumped = json.dumps(val, ensure_ascii=False).replace("'", "''")
        return f"'{dumped}'::jsonb"

    str_val = str(val).strip()
    if not str_val:
        return 'NULL' if target_type in ('INTEGER', 'BIGINT', 'DOUBLE PRECISION', 'DATE', 'TIMESTAMPTZ') else "''"

    # Conversão de datas com sufixo Z ou ISO
    if target_type == 'DATE':
        # Se for 2025-01-27Z, limpa o Z para formato puro date
        clean_date = str_val.replace('Z', '').split('T')[0]
        return f"'{clean_date}'::date"
    if target_type == 'TIMESTAMPTZ':
        return f"'{str_val}'::timestamptz"

    escaped = str_val.replace("'", "''")
    return f"'{escaped}'"


def generate_table_inserts(schema_obj: TableSchema, schema: str = 'public', batch_size: int = 500) -> List[str]:
    """Gera blocos de comandos INSERT com ST_Multi(ST_SetSRID(ST_GeomFromGeoJSON(...), SRID))."""
    with open(schema_obj.filepath, 'r', encoding='utf-8') as fp:
        data = json.load(fp)

    features = data.get('features', [])
    if not features:
        return []

    field_names = list(schema_obj.fields.keys())
    full_table = f'"{schema}"."{schema_obj.table_name}"'

    columns_sql = [f'"{f}"' for f in field_names]
    if schema_obj.has_geom:
        columns_sql.append('"geom"')
    cols_header = ', '.join(columns_sql)

    statements: List[str] = []
    current_values_batch: List[str] = []

    for feat in features:
        props = feat.get('properties') or {}
        row_vals: List[str] = []

        for field_name in field_names:
            val = props.get(field_name)
            target_type = schema_obj.fields[field_name].infer_postgres_type()
            row_vals.append(escape_sql_val(val, target_type))

        if schema_obj.has_geom:
            geom = feat.get('geometry')
            if geom:
                geom_json = json.dumps(geom, ensure_ascii=False).replace("'", "''")
                # ST_Multi garante conversão transparente para MultiPolygon
                row_vals.append(f"ST_Multi(ST_SetSRID(ST_GeomFromGeoJSON('{geom_json}'), {schema_obj.srid}))")
            else:
                row_vals.append('NULL')

        current_values_batch.append(f"({', '.join(row_vals)})")

        if len(current_values_batch) >= batch_size:
            sql = f"INSERT INTO {full_table} ({cols_header}) VALUES\n" + ',\n'.join(current_values_batch) + ';'
            statements.append(sql)
            current_values_batch = []

    if current_values_batch:
        sql = f"INSERT INTO {full_table} ({cols_header}) VALUES\n" + ',\n'.join(current_values_batch) + ';'
        statements.append(sql)

    return statements


# ==============================================================================
# 3. EXECUTOR POSTGRESQL / POSTGIS
# ==============================================================================

def execute_sql_in_postgres(sql_content: str, host: str, port: int, user: str, dbname: str, password: Optional[str] = None) -> None:
    """Executa o script SQL diretamente via psql no PostgreSQL."""
    env = os.environ.copy()
    if password:
        env['PGPASSWORD'] = password

    with tempfile.NamedTemporaryFile('w', suffix='.sql', encoding='utf-8', delete=False) as tf:
        tf.write(sql_content)
        temp_path = tf.name

    try:
        cmd = [
            'psql',
            '-h', host,
            '-p', str(port),
            '-U', user,
            '-d', dbname,
            '-v', 'ON_ERROR_STOP=1',
            '-f', temp_path,
        ]
        result = subprocess.run(cmd, env=env, capture_output=True, text=True, encoding='utf-8')
        if result.returncode != 0:
            sys.stderr.write(f"\n[ERRO AO EXECUTAR SQL VIA PSQL]\n{result.stderr}\n")
            raise RuntimeError(f"psql falhou com código {result.returncode}")
    finally:
        if os.path.exists(temp_path):
            os.remove(temp_path)


# ==============================================================================
# 4. FORMATAÇÃO E INTERFACE CLI
# ==============================================================================

def sanitize_table_name(filename: str, prefix: str = 'geo_') -> str:
    """Converte o nome do arquivo geojson para um nome de tabela SQL válido."""
    base = os.path.splitext(os.path.basename(filename))[0].lower()
    clean = re.sub(r'[^a-z0-9_]', '_', base)
    clean = re.sub(r'_+', '_', clean).strip('_')
    if prefix and not clean.startswith(prefix):
        clean = f"{prefix}{clean}"
    return clean


def print_table_report(schema_obj: TableSchema) -> None:
    """Exibe um relatório tabular elegante no terminal."""
    print("=" * 80)
    print(f"📁 ARQUIVO: {schema_obj.filename}")
    print(f"📊 TABELA:  {schema_obj.table_name}")
    print(f"📍 FEIÇÕES: {schema_obj.feature_count:,} | GEOMETRIA: {schema_obj.geometry_type} (SRID {schema_obj.srid})")
    if schema_obj.pk_field:
        print(f"🔑 CHAVE PRIMÁRIA: {schema_obj.pk_field} (automática)")
    print("-" * 80)
    print(f"{'COLUNA':<22} | {'TIPO POSTGRES':<18} | {'NULOS':<10} | {'AMOSTRA'}")
    print("-" * 80)

    for col_name, st in sorted(schema_obj.fields.items()):
        pg_type = st.infer_postgres_type()
        null_info = f"{st.null_count}/{st.total_count}"
        sample = list(st.distinct_samples)[0] if st.distinct_samples else '-'
        print(f"{col_name:<22} | {pg_type:<18} | {null_info:<10} | {sample}")

    if schema_obj.has_geom:
        print(f"{'geom':<22} | {f'geometry({schema_obj.geometry_type}, {schema_obj.srid})':<18} | {'0/total':<10} | PostGIS Geometry")
    print("=" * 80 + "\n")


def main() -> int:
    parser = argparse.ArgumentParser(
        description="Analisa GeoJSONs e cria tabelas correspondentes no PostgreSQL + PostGIS.",
        formatter_class=argparse.RawDescriptionHelpFormatter,
    )
    parser.add_argument(
        'files',
        nargs='*',
        default=['geojson/*.geojson'],
        help="Caminhos ou globs para arquivos .geojson (padrão: geojson/*.geojson)",
    )
    parser.add_argument('--host', default=os.environ.get('PGHOST', 'localhost'), help="Host do PostgreSQL (padrão: localhost)")
    parser.add_argument('--port', type=int, default=int(os.environ.get('PGPORT', 5432)), help="Porta do PostgreSQL (padrão: 5432)")
    parser.add_argument('--user', default=os.environ.get('PGUSER', 'postgres'), help="Usuário do PostgreSQL (padrão: postgres)")
    parser.add_argument('--password', default=os.environ.get('PGPASSWORD'), help="Senha do PostgreSQL (opcional)")
    parser.add_argument('--dbname', default=os.environ.get('PGDATABASE', 'db_geo'), help="Nome do Banco de Dados (padrão: db_geo)")
    parser.add_argument('--schema', default='public', help="Schema do banco de dados (padrão: public)")
    parser.add_argument('--table-prefix', default='geo_', help="Prefixo para as tabelas criadas (padrão: geo_)")
    parser.add_argument('--srid', type=int, default=4326, help="SRID para geometrias (padrão: 4326 - WGS84)")
    parser.add_argument('--output-sql', help="Salva todo o DDL gerado em um arquivo .sql")
    parser.add_argument('--execute', action='store_true', help="Executa o DDL no PostgreSQL + PostGIS criando as tabelas")
    parser.add_argument('--import-data', action='store_true', help="Importa todos os dados das feições para as tabelas criadas")
    parser.add_argument('--drop-existing', action='store_true', help="Derruba tabelas existentes antes de recriar (DROP CASCADE)")
    parser.add_argument('--batch-size', type=int, default=500, help="Tamanho do lote para inserção de dados (padrão: 500)")

    args = parser.parse_args()

    # Expande padrões de arquivo
    target_files: List[str] = []
    for pattern in args.files:
        matches = glob.glob(pattern)
        if matches:
            target_files.extend(matches)
        elif os.path.isfile(pattern):
            target_files.append(pattern)

    target_files = sorted(list(set(target_files)))

    if not target_files:
        print(f"❌ Nenhum arquivo GeoJSON encontrado para o padrão: {args.files}")
        return 1

    print(f"\n🚀 Iniciando análise estrutural de {len(target_files)} arquivo(s) GeoJSON...\n")

    schemas: List[TableSchema] = []
    total_features = 0

    for fpath in target_files:
        tbl_name = sanitize_table_name(fpath, prefix=args.table_prefix)
        schema_obj = TableSchema(filepath=fpath, table_name=tbl_name, srid=args.srid)
        schema_obj.analyze()
        schemas.append(schema_obj)
        total_features += schema_obj.feature_count
        print_table_report(schema_obj)

    # 1. Monta o script DDL completo
    ddl_parts: List[str] = [
        "-- ============================================================================",
        f"-- DDL AUTOMÁTICO POSTGIS GERADO EM {datetime.now().strftime('%Y-%m-%d %H:%M:%S')}",
        "-- ============================================================================",
        "CREATE EXTENSION IF NOT EXISTS postgis;",
        f"CREATE SCHEMA IF NOT EXISTS \"{args.schema}\";",
        "",
    ]

    for s in schemas:
        ddl_parts.append(s.generate_ddl(schema=args.schema, drop_existing=args.drop_existing))

    full_ddl = '\n'.join(ddl_parts)

    # 2. Salva arquivo SQL se solicitado
    if args.output_sql:
        with open(args.output_sql, 'w', encoding='utf-8') as f:
            f.write(full_ddl)
        print(f"💾 Script DDL gerado com sucesso em: {args.output_sql}")

    # 3. Executa no PostgreSQL se solicitado
    if args.execute:
        print(f"🔌 Conectando ao PostgreSQL ({args.host}:{args.port} / {args.dbname} - usuário: {args.user})...")
        start_t = time.time()
        try:
            execute_sql_in_postgres(
                full_ddl,
                host=args.host,
                port=args.port,
                user=args.user,
                dbname=args.dbname,
                password=args.password,
            )
            print(f"✅ Tabelas e índices espaciais criados com sucesso em {time.time() - start_t:.2f}s!")
        except Exception as e:
            print(f"❌ Falha ao criar tabelas no PostgreSQL: {e}")
            return 1

        # 4. Importa dados se solicitado
        if args.import_data:
            print(f"\n📦 Iniciando importação de dados ({total_features:,} feições no total)...")
            import_start = time.time()
            for s in schemas:
                print(f"   ⏳ Inserindo dados em '{s.table_name}' ({s.feature_count:,} registros)...", end='', flush=True)
                t0 = time.time()
                inserts = generate_table_inserts(s, schema=args.schema, batch_size=args.batch_size)
                if inserts:
                    full_inserts_sql = "BEGIN;\n" + '\n'.join(inserts) + "\nCOMMIT;"
                    execute_sql_in_postgres(
                        full_inserts_sql,
                        host=args.host,
                        port=args.port,
                        user=args.user,
                        dbname=args.dbname,
                        password=args.password,
                    )
                print(f" Concluído em {time.time() - t0:.2f}s.")
            print(f"🎉 Importação completa concluída com sucesso em {time.time() - import_start:.2f}s!\n")
    else:
        print("💡 DICA: Para criar as tabelas no banco de dados local, execute:")
        print(f"    python scripts/analisar_geojson_postgis.py --execute")
        print("💡 Para criar as tabelas E já importar todas as feições:")
        print(f"    python scripts/analisar_geojson_postgis.py --execute --import-data\n")

    return 0


if __name__ == '__main__':
    sys.exit(main())
OMNI_EOF

# --- scripts/carregar_geojson_sqlite.py ---
cat > 'scripts/carregar_geojson_sqlite.py' <<'OMNI_EOF'
#!/usr/bin/env python3
"""
Script de Análise Estrutural de Arquivos GeoJSON e Criação de Tabelas SQLite com Indexação Espacial.

Lê e analisa os arquivos .geojson do diretório geojson/, infere os tipos
corretos de cada coluna (INTEGER, REAL, TEXT), calcula bounding boxes (min/max lat e lng),
centróides geométricos, armazena a geometria GeoJSON completa e cria índices
B-Tree e R*Tree espaciais diretamente no SQLite (instance/app_clientes.db).

Uso:
    # Apenas analisar e exibir o relatório de tipos no terminal:
    python scripts/carregar_geojson_sqlite.py

    # Gerar arquivo SQL DDL:
    python scripts/carregar_geojson_sqlite.py --output-sql schema_geo_sqlite.sql

    # Executar DDL e importar todos os dados para o SQLite (instance/app_clientes.db):
    python scripts/carregar_geojson_sqlite.py --execute

    # Limpar tabelas anteriores e reimportar:
    python scripts/carregar_geojson_sqlite.py --execute --clean

Parâmetros adicionais:
    --db instance/app_clientes.db    (caminho para o banco SQLite)
    --geojson-dir geojson            (pasta contendo os arquivos .geojson)
    --table-prefix geo_              (prefixo das tabelas geradas)
    --batch-size 1000                (tamanho do lote para executemany)
"""

import argparse
import glob
import json
import math
import os
import re
import sqlite3
import sys
import time
from datetime import datetime
from pathlib import Path
from typing import Any, Dict, List, Optional, Set, Tuple

ROOT = Path(__file__).resolve().parent.parent
DEFAULT_DB = ROOT / 'instance' / 'app_clientes.db'
DEFAULT_GEOJSON_DIR = ROOT / 'geojson'

ISO_DATE_REGEX = re.compile(r'^\d{4}-\d{2}-\d{2}(?:Z|[+-]\d{2}:?\d{2})?$')
ISO_DATETIME_REGEX = re.compile(r'^\d{4}-\d{2}-\d{2}[T\s]\d{2}:\d{2}:\d{2}(?:\.\d+)?(?:Z|[+-]\d{2}:?\d{2})?$')


class FieldStats:
    """Acumula estatísticas e tipos observados em uma propriedade GeoJSON."""

    def __init__(self, name: str):
        self.name = name
        self.observed_types: Set[str] = set()
        self.total_count = 0
        self.null_count = 0
        self.min_val: Any = None
        self.max_val: Any = None
        self.max_str_len = 0
        self.distinct_samples: Set[Any] = set()

    def record_value(self, val: Any) -> None:
        self.total_count += 1
        if val is None:
            self.null_count += 1
            return

        if len(self.distinct_samples) < 5:
            self.distinct_samples.add(str(val)[:40])

        if isinstance(val, bool):
            self.observed_types.add('int')
        elif isinstance(val, int):
            self.observed_types.add('int')
            self._update_min_max(val)
        elif isinstance(val, float):
            self.observed_types.add('float')
            self._update_min_max(val)
        elif isinstance(val, str):
            clean = val.strip()
            self.max_str_len = max(self.max_str_len, len(clean))
            if clean.isdigit() and not (len(clean) > 1 and clean.startswith('0')):
                self.observed_types.add('int')
            else:
                self.observed_types.add('str')
        elif isinstance(val, (dict, list)):
            self.observed_types.add('str')
        else:
            self.observed_types.add('str')

    def _update_min_max(self, val: Any) -> None:
        if self.min_val is None or val < self.min_val:
            self.min_val = val
        if self.max_val is None or val > self.max_val:
            self.max_val = val

    def infer_sqlite_type(self) -> str:
        """Determina o tipo ideal de dado do SQLite (INTEGER, REAL, TEXT)."""
        types = self.observed_types - {'null'}
        if not types:
            return 'TEXT'
        if types == {'int'}:
            return 'INTEGER'
        if types in ({'float'}, {'int', 'float'}):
            return 'REAL'
        return 'TEXT'


# Constantes geodésicas SIRGAS 2000 / WGS84 para Zona UTM 21S (EPSG:31981 -> EPSG:4326)
_UTM_A = 6378137.0
_UTM_F = 1.0 / 298.257222101
_UTM_K0 = 0.9996
_UTM_E2 = 2.0 * _UTM_F - _UTM_F * _UTM_F
_UTM_E1 = (1.0 - math.sqrt(1.0 - _UTM_E2)) / (1.0 + math.sqrt(1.0 - _UTM_E2))
_UTM_EP2 = _UTM_E2 / (1.0 - _UTM_E2)
_UTM_M_DENOM = _UTM_A * (1.0 - _UTM_E2 / 4.0 - 3.0 * _UTM_E2 * _UTM_E2 / 64.0 - 5.0 * (_UTM_E2 ** 3) / 256.0)
_UTM_C1 = 3.0 * _UTM_E1 / 2.0 - 27.0 * (_UTM_E1 ** 3) / 32.0
_UTM_C2 = 21.0 * (_UTM_E1 ** 2) / 16.0 - 55.0 * (_UTM_E1 ** 4) / 32.0
_UTM_C3 = 151.0 * (_UTM_E1 ** 3) / 96.0
_UTM_C4 = 1097.0 * (_UTM_E1 ** 4) / 512.0
_UTM_LON0 = math.radians(-57.0)  # Meridiano central da Zona 21S
_RAD2DEG = 57.29577951308232


def utm21s_to_wgs84(easting: float, northing: float, ndigits: int = 6) -> Tuple[float, float]:
    """
    Converte coordenadas métricas UTM Zona 21S (EPSG:31981 - SIRGAS 2000)
    para graus decimais WGS84 (EPSG:4326 - longitude, latitude).
    """
    x = easting - 500000.0
    y = northing - 10000000.0
    mu = (y / _UTM_K0) / _UTM_M_DENOM
    phi1 = (
        mu
        + _UTM_C1 * math.sin(2.0 * mu)
        + _UTM_C2 * math.sin(4.0 * mu)
        + _UTM_C3 * math.sin(6.0 * mu)
        + _UTM_C4 * math.sin(8.0 * mu)
    )
    sin_p = math.sin(phi1)
    cos_p = math.cos(phi1)
    tan_p = math.tan(phi1)
    w = 1.0 - _UTM_E2 * sin_p * sin_p
    n1 = _UTM_A / math.sqrt(w)
    t1 = tan_p * tan_p
    c1 = _UTM_EP2 * cos_p * cos_p
    r1 = _UTM_A * (1.0 - _UTM_E2) / (w * math.sqrt(w))
    d = x / (n1 * _UTM_K0)
    d2 = d * d
    d4 = d2 * d2
    lat = phi1 - (n1 * tan_p / r1) * (
        d2 / 2.0
        - (5.0 + 3.0 * t1 + 10.0 * c1 - 4.0 * c1 * c1 - 9.0 * _UTM_EP2) * d4 / 24.0
    )
    lon = _UTM_LON0 + (
        d
        - (1.0 + 2.0 * t1 + c1) * d2 * d / 6.0
        + (5.0 - 2.0 * c1 + 28.0 * t1 - 3.0 * c1 * c1 + 8.0 * _UTM_EP2 + 24.0 * t1 * t1) * d4 * d / 120.0
    ) / cos_p
    return round(lon * _RAD2DEG, ndigits), round(lat * _RAD2DEG, ndigits)


def extract_coordinates_and_bounds(
    geometry: Dict[str, Any],
    reproject_in_place: bool = True
) -> Tuple[str, Tuple[float, float, float, float], Tuple[float, float]]:
    """
    Extrai tipo de geometria, bounding box (min_lng, min_lat, max_lng, max_lat)
    e centróide aproximado (centroid_lat, centroid_lng).
    Se as coordenadas estiverem em projeção UTM métrica (EPSG:31981, |x| > 180 ou |y| > 90),
    converte automaticamente para WGS84 (EPSG:4326).
    """
    g_type = geometry.get('type', 'Geometry')
    coords = geometry.get('coordinates', [])

    all_points: List[Tuple[float, float]] = []

    def walk_coords(c: Any) -> None:
        if isinstance(c, list):
            if len(c) >= 2 and isinstance(c[0], (int, float)) and isinstance(c[1], (int, float)):
                x, y = float(c[0]), float(c[1])
                if abs(x) > 180.0 or abs(y) > 90.0:
                    x, y = utm21s_to_wgs84(x, y)
                    if reproject_in_place:
                        c[0], c[1] = x, y
                elif reproject_in_place:
                    c[0], c[1] = round(x, 6), round(y, 6)
                all_points.append((x, y))
            else:
                for item in c:
                    walk_coords(item)
        elif isinstance(c, tuple):
            if len(c) >= 2 and isinstance(c[0], (int, float)) and isinstance(c[1], (int, float)):
                x, y = float(c[0]), float(c[1])
                if abs(x) > 180.0 or abs(y) > 90.0:
                    x, y = utm21s_to_wgs84(x, y)
                all_points.append((x, y))
            else:
                for item in c:
                    walk_coords(item)

    walk_coords(coords)

    if not all_points:
        return g_type, (-54.62, -20.45, -54.62, -20.45), (-20.45, -54.62)

    min_lng = min(p[0] for p in all_points)
    max_lng = max(p[0] for p in all_points)
    min_lat = min(p[1] for p in all_points)
    max_lat = max(p[1] for p in all_points)

    centroid_lng = round(sum(p[0] for p in all_points) / len(all_points), 6)
    centroid_lat = round(sum(p[1] for p in all_points) / len(all_points), 6)

    return g_type, (min_lng, min_lat, max_lng, max_lat), (centroid_lat, centroid_lng)


class GeoJsonTable:
    """Representa uma camada GeoJSON a ser importada no SQLite."""

    def __init__(self, filepath: str, table_name: str):
        self.filepath = filepath
        self.filename = os.path.basename(filepath)
        self.table_name = table_name
        self.fields: Dict[str, FieldStats] = {}
        self.prop_key_map: Dict[str, str] = {}
        self.col_to_orig_key: Dict[str, str] = {}
        self.features: List[Dict[str, Any]] = []
        self.feature_bounds: List[Tuple[str, Tuple[float, float, float, float], Tuple[float, float]]] = []
        self.geometry_type = 'Geometry'
        self.bbox: Tuple[float, float, float, float] = (0, 0, 0, 0)

    def analyze(self) -> None:
        with open(self.filepath, 'r', encoding='utf-8') as f:
            data = json.load(f)

        self.features = data.get('features', [])
        self.feature_bounds = []
        all_lons: List[float] = []
        all_lats: List[float] = []

        for feat in self.features:
            geom = feat.get('geometry')
            if geom:
                g_type, (min_x, min_y, max_x, max_y), cent = extract_coordinates_and_bounds(geom, reproject_in_place=True)
                self.geometry_type = g_type
                self.feature_bounds.append((g_type, (min_x, min_y, max_x, max_y), cent))
                all_lons.extend([min_x, max_x])
                all_lats.extend([min_y, max_y])
            else:
                self.feature_bounds.append(('Geometry', (-54.62, -20.45, -54.62, -20.45), (-20.45, -54.62)))

            props = feat.get('properties') or {}
            for k, v in props.items():
                col = self.prop_key_map.get(k)
                if col is None:
                    col = re.sub(r'[^a-zA-Z0-9_]', '_', k.strip().lower()) or 'col'
                    self.prop_key_map[k] = col
                    self.col_to_orig_key[col] = k
                    if col not in self.fields:
                        self.fields[col] = FieldStats(col)
                self.fields[col].record_value(v)

        if all_lons and all_lats:
            self.bbox = (min(all_lons), min(all_lats), max(all_lons), max(all_lats))

    def generate_ddl(self) -> List[str]:
        """Gera comandos SQL DDL para a tabela principal e índices espaciais."""
        col_defs = ["id INTEGER PRIMARY KEY AUTOINCREMENT"]
        for col, stats in self.fields.items():
            if col == 'id':
                continue
            sqlite_type = stats.infer_sqlite_type()
            col_defs.append(f'"{col}" {sqlite_type}')

        # Colunas espaciais padronizadas
        col_defs.extend([
            "geometry_geojson TEXT",
            "geometry_type TEXT",
            "min_lng REAL",
            "min_lat REAL",
            "max_lng REAL",
            "max_lat REAL",
            "centroid_lat REAL",
            "centroid_lng REAL",
            "created_at TEXT DEFAULT (datetime('now'))"
        ])

        ddl = [
            f'CREATE TABLE IF NOT EXISTS "{self.table_name}" (\n    ' + ',\n    '.join(col_defs) + '\n);',
            f'CREATE INDEX IF NOT EXISTS "idx_{self.table_name}_bbox" ON "{self.table_name}" (min_lng, min_lat, max_lng, max_lat);',
            f'CREATE INDEX IF NOT EXISTS "idx_{self.table_name}_centroid" ON "{self.table_name}" (centroid_lat, centroid_lng);',
        ]

        # Índices úteis para atributos textuais frequentes
        for col in self.fields.keys():
            if col in (
                'nome', 'bairro', 'nm_bairro', 'nomebairro', 'regiao_urbana',
                'nomeregiao', 'logradouro', 'ruaimo', 'usoimovel', 'codlote',
                'inscricao', 'cep'
            ):
                ddl.append(f'CREATE INDEX IF NOT EXISTS "idx_{self.table_name}_{col}" ON "{self.table_name}" ("{col}");')

        # Virtual Table R*Tree para buscas geométricas ultra-rápidas (se suportado)
        rtree_name = f"{self.table_name}_rtree"
        ddl.append(f'CREATE VIRTUAL TABLE IF NOT EXISTS "{rtree_name}" USING rtree(id, min_lng, max_lng, min_lat, max_lat);')

        return ddl


def main():
    parser = argparse.ArgumentParser(
        description="Analisa arquivos GeoJSON e cria tabelas estruturadas no SQLite com índices espaciais."
    )
    parser.add_argument('--db', default=str(DEFAULT_DB), help="Caminho do banco SQLite (padrão: instance/app_clientes.db)")
    parser.add_argument('--geojson-dir', default=str(DEFAULT_GEOJSON_DIR), help="Diretório dos arquivos .geojson")
    parser.add_argument('--table-prefix', default='geo_', help="Prefixo para as tabelas criadas (padrão: geo_)")
    parser.add_argument('--execute', action='store_true', help="Executa a criação das tabelas e importação dos dados no SQLite")
    parser.add_argument('--clean', action='store_true', help="Remove tabelas existentes antes de recriar")
    parser.add_argument('--skip-imoveis', action='store_true', help="Pula imoveis.geojson (quando restaurado via scripts/restaurar_imoveis.py)")
    parser.add_argument('--only', help="Processa apenas o arquivo cujo nome contenha este termo (ex: imoveis)")
    parser.add_argument('--output-sql', help="Salva os comandos DDL gerados em um arquivo SQL")
    parser.add_argument('--batch-size', type=int, default=2000, help="Tamanho do lote para inserção (padrão: 2000)")
    parser.add_argument('--quiet', action='store_true', help="Suprime saída detalhada no terminal")

    args = parser.parse_args()

    geojson_dir = Path(args.geojson_dir)
    if not geojson_dir.exists():
        print(f"❌ Diretório não encontrado: {geojson_dir}")
        sys.exit(1)

    arquivos = sorted(glob.glob(str(geojson_dir / '*.geojson')))
    usar_dump_imoveis = False
    dump_imoveis_path = ROOT / 'data' / 'geo_imoveis.sql.gz'

    if args.skip_imoveis:
        arquivos = [a for a in arquivos if Path(a).name != 'imoveis.geojson']
    elif not args.only and not args.clean and dump_imoveis_path.exists():
        # Usa o dump comprimido data/geo_imoveis.sql.gz em vez de reprocessar os 469 MB brutos
        arquivos = [a for a in arquivos if Path(a).name != 'imoveis.geojson']
        usar_dump_imoveis = True

    if args.only:
        termo = args.only.lower().strip()
        arquivos = [a for a in arquivos if termo in Path(a).name.lower()]

    if not arquivos and not usar_dump_imoveis:
        print(f"❌ Nenhum arquivo .geojson encontrado em: {geojson_dir}")
        sys.exit(1)

    print("=" * 80)
    print("📍 ANÁLISE E CARREGAMENTO DE GEOJSON NO SQLITE COM SUPORTE ESPACIAL")
    print("=" * 80)
    print(f"Diretório GeoJSON: {geojson_dir}")
    print(f"Banco SQLite:      {args.db}")
    print(f"Arquivos achados:  {len(arquivos)}" + (" (+ dump comprimido geo_imoveis.sql.gz)" if usar_dump_imoveis else ""))
    print(f"Modo de execução:  {'EXECUTAR CRIAÇÃO E CARGA' if args.execute else 'APENAS ANÁLISE (DRY-RUN)'}")
    print("=" * 80)

    tables: List[GeoJsonTable] = []
    total_features = 0

    for arq in arquivos:
        base = Path(arq).stem
        sanitized = re.sub(r'[^a-zA-Z0-9_]', '_', base.lower())
        table_name = f"{args.table_prefix}{sanitized}"
        gt = GeoJsonTable(arq, table_name)
        gt.analyze()
        tables.append(gt)
        total_features += len(gt.features)

        if not args.quiet:
            print(f"\n📂 Arquivo: {gt.filename}")
            print(f"   Tabela:    {gt.table_name}")
            print(f"   Features:  {len(gt.features):,}")
            print(f"   Geometria: {gt.geometry_type}")
            print(f"   Bounds:    LNG [{gt.bbox[0]:.4f}, {gt.bbox[2]:.4f}] | LAT [{gt.bbox[1]:.4f}, {gt.bbox[3]:.4f}]")
            print("   Colunas Inferidas:")
            for col, stats in gt.fields.items():
                print(f"     - {col:<24} {stats.infer_sqlite_type():<8} (não-nulos: {stats.total_count - stats.null_count}/{stats.total_count})")

    if usar_dump_imoveis and not args.quiet:
        print(f"\n📦 Dump Comprimido: {dump_imoveis_path.name} ({dump_imoveis_path.stat().st_size / (1024*1024):.2f} MB)")
        print("   Tabela:    geo_imoveis (+ geo_imoveis_rtree)")
        print("   Features:  462,744 (MultiPolygon reprojetado para WGS84)")

    # Gera SQL DDL consolidado
    all_ddl: List[str] = []
    for gt in tables:
        all_ddl.extend(gt.generate_ddl())

    if args.output_sql:
        with open(args.output_sql, 'w', encoding='utf-8') as f:
            f.write("-- DDL gerado para camadas GeoJSON no SQLite\n\n")
            f.write("\n\n".join(all_ddl))
            f.write("\n")
        print(f"\n💾 DDL salvo com sucesso em: {args.output_sql}")

    if not args.execute:
        print("\n💡 Para criar as tabelas e carregar os dados no SQLite, rode:")
        print("   python scripts/carregar_geojson_sqlite.py --execute")
        return

    # Execução no SQLite
    db_path = Path(args.db)
    db_path.parent.mkdir(parents=True, exist_ok=True)
    con = sqlite3.connect(str(db_path))
    cur = con.cursor()

    # Otimizações pragmas de performance para inserção em lote
    cur.execute("PRAGMA synchronous = OFF;")
    cur.execute("PRAGMA journal_mode = MEMORY;")
    cur.execute("PRAGMA cache_size = -64000;")  # 64MB cache
    cur.execute("PRAGMA temp_store = MEMORY;")

    inicio_total = time.time()

    for gt in tables:
        t_inicio = time.time()
        print(f"\n🚀 Processando tabela {gt.table_name}...")

        cur.execute(f'DROP TABLE IF EXISTS "{gt.table_name}_rtree";')
        cur.execute(f'DROP TABLE IF EXISTS "{gt.table_name}";')

        # Cria apenas a tabela primeiro (índices criados após o bulk insert para máxima velocidade)
        ddl_cmds = gt.generate_ddl()
        cur.execute(ddl_cmds[0])

        # Prepara inserção de dados
        field_names = [f for f in gt.fields.keys() if f != 'id']
        orig_keys = [gt.col_to_orig_key[f] for f in field_names]
        cols = ['"' + f + '"' for f in field_names] + [
            "geometry_geojson", "geometry_type", "min_lng", "min_lat", "max_lng", "max_lat", "centroid_lat", "centroid_lng"
        ]
        placeholders = ', '.join(['?'] * len(cols))
        insert_sql = f'INSERT INTO "{gt.table_name}" ({", ".join(cols)}) VALUES ({placeholders})'

        batch_rows: List[List[Any]] = []
        inserted = 0

        for idx, feat in enumerate(gt.features):
            props = feat.get('properties') or {}
            geom = feat.get('geometry') or {}
            g_type, (min_lng, min_lat, max_lng, max_lat), (cent_lat, cent_lng) = gt.feature_bounds[idx]

            row: List[Any] = []
            for orig_k in orig_keys:
                val = props.get(orig_k)
                if isinstance(val, (dict, list)):
                    val = json.dumps(val, ensure_ascii=False, separators=(',', ':'))
                row.append(val)

            geom_json_str = json.dumps(geom, ensure_ascii=False, separators=(',', ':')) if geom else None
            row.extend([
                geom_json_str,
                g_type,
                min_lng, min_lat, max_lng, max_lat,
                cent_lat, cent_lng
            ])
            batch_rows.append(row)

            if len(batch_rows) >= args.batch_size:
                cur.executemany(insert_sql, batch_rows)
                inserted += len(batch_rows)
                batch_rows = []

        if batch_rows:
            cur.executemany(insert_sql, batch_rows)
            inserted += len(batch_rows)

        # Cria índices B-Tree e R*Tree após a carga em lote (muito mais rápido)
        for cmd in ddl_cmds[1:]:
            try:
                cur.execute(cmd)
            except Exception as e:
                if "rtree" in cmd.lower():
                    pass
                else:
                    raise e

        # Popula o RTree diretamente via SQL
        try:
            cur.execute(
                f'INSERT OR REPLACE INTO "{gt.table_name}_rtree" '
                f'SELECT id, min_lng, max_lng, min_lat, max_lat FROM "{gt.table_name}";'
            )
        except Exception:
            pass

        t_fim = time.time()
        print(f"   ✅ {inserted:,} registros inseridos com sucesso ({t_fim - t_inicio:.2f}s).")

    con.commit()
    con.close()

    if usar_dump_imoveis:
        if str(ROOT) not in sys.path:
            sys.path.insert(0, str(ROOT))
        from scripts.restaurar_imoveis import restaurar_dump, verificar_tabela_existente
        restaurar_dump(dump_imoveis_path, db_path, force=False)
        con_chk = sqlite3.connect(str(db_path))
        total_features += verificar_tabela_existente(con_chk)
        con_chk.close()

    tempo_total = time.time() - inicio_total
    print("\n" + "=" * 80)
    print(f"🎉 SUCESSO! {total_features:,} features disponíveis nas tabelas espaciais do SQLite em {tempo_total:.2f}s.")
    print("=" * 80)


if __name__ == '__main__':
    main()
OMNI_EOF

# --- scripts/enriquecer_clientes_rfb.py ---
cat > 'scripts/enriquecer_clientes_rfb.py' <<'OMNI_EOF'
#!/usr/bin/env python3
"""
Enriquece a tabela de clientes do SQLite (app_clientes.db) com dados reais
da Receita Federal do Brasil (RFB) armazenados na tabela leeds_campo_grande.

Utiliza a inteligência geográfica de bairros, CEPs e ruas do SISGRAN/PLANURB
para localizar corretamente cada empresa em seu respectivo bairro oficial e rua real
de Campo Grande - MS.

Uso:
    # Importar 150 clientes distribuídos de forma equilibrada por todos os bairros:
    python scripts/enriquecer_clientes_rfb.py

    # Importar uma quantidade específica (ex: 300 clientes):
    python scripts/enriquecer_clientes_rfb.py --limit 300

    # Simular a importação (sem gravar no banco):
    python scripts/enriquecer_clientes_rfb.py --dry-run
"""

import argparse
import os
import re
import sqlite3
import sys
from datetime import datetime
from pathlib import Path
from typing import Dict, Any, List, Optional, Set

ROOT = Path(__file__).resolve().parent.parent
DB_PATH = ROOT / 'instance' / 'app_clientes.db'

# Adiciona o diretório raiz ao sys.path para importar app.data.perfis_sisgran
sys.path.insert(0, str(ROOT))
from app.data.perfis_sisgran import (
    PERFIS_CAMPO_GRANDE,
    CEP_PREFIXOS_BAIRROS,
    resolver_bairro,
    normalizar_bairro,
    obter_perfil_bairro,
    obter_ruas_bairro,
    obter_imoveis_amostra,
)


def format_cnpj(cnpj_raw: str) -> str:
    """Formata CNPJ no padrão XX.XXX.XXX/XXXX-XX."""
    digits = re.sub(r'\D', '', str(cnpj_raw or ''))
    if len(digits) == 14:
        return f"{digits[:2]}.{digits[2:5]}.{digits[5:8]}/{digits[8:12]}-{digits[12:]}"
    return digits


def format_telefone(tel_raw: str) -> str:
    """
    Formata telefone brasileiro (padrão DDD 67).
    Realiza o split por '|' quando existirem múltiplos números concatenados na RFB,
    pegando sempre o primeiro número da lista e removendo prefixo DDI +55.
    """
    if not tel_raw:
        return '(67) 3300-1000'
    primeiro = str(tel_raw).split('|')[0].strip()
    digits = re.sub(r'\D', '', primeiro)
    if not digits:
        return '(67) 3300-1000'

    # Remove DDI 55 do Brasil se presente
    if digits.startswith('55') and len(digits) >= 10:
        digits = digits[2:]

    # Extrai DDD (2 dígitos) e número local
    if len(digits) in (10, 11):
        ddd = digits[:2]
        num = digits[2:]
    elif len(digits) in (8, 9):
        ddd = '67'
        num = digits
    elif len(digits) > 11:
        ddd = digits[:2]
        num = digits[2:11]
    else:
        return f"(67) 9{digits.zfill(8)[:4]}-{digits.zfill(8)[4:]}"

    if len(num) == 9:
        return f"({ddd}) {num[:5]}-{num[5:]}"
    elif len(num) == 8:
        if num[0] in ('8', '9'):
            return f"({ddd}) 9{num[:4]}-{num[4:]}"
        else:
            return f"({ddd}) {num[:4]}-{num[4:]}"
    return f"({ddd}) {num}"


def format_cep(cep_raw: str) -> str:
    """Formata CEP no padrão 79000-000."""
    digits = re.sub(r'\D', '', str(cep_raw or ''))
    if len(digits) >= 8:
        return f"{digits[:5]}-{digits[5:8]}"
    elif len(digits) == 5:
        return f"{digits}-000"
    return "79002-000"


def clean_str(val: Any) -> str:
    """Remove aspas extras e espaços."""
    if val is None:
        return ''
    s = str(val).strip()
    if (s.startswith("'") and s.endswith("'")) or (s.startswith('"') and s.endswith('"')):
        s = s[1:-1].strip()
    return s


def title_case(text: str) -> str:
    if not text:
        return ''
    words = text.strip().split()
    lowers = {'de', 'da', 'do', 'dos', 'das', 'e', 'em', 'para', 'com', 'ltda', 'me', 'epp'}
    uppers = {'ltda', 's/a', 'sa', 'me', 'epp', 'eireli'}
    result = []
    for i, w in enumerate(words):
        wl = w.lower()
        if wl in uppers:
            result.append(wl.upper())
        elif i > 0 and wl in lowers:
            result.append(wl)
        else:
            result.append(w.capitalize())
    return ' '.join(result)


def resolver_bairro_por_cep(cep_digits: str) -> str:
    """Resolve o bairro oficial de Campo Grande a partir do prefixo do CEP no formato canônico."""
    bairro_candidato = None
    prefix5 = cep_digits[:5]
    if prefix5 in CEP_PREFIXOS_BAIRROS:
        bairro_candidato = CEP_PREFIXOS_BAIRROS[prefix5]
    else:
        prefix4 = cep_digits[:4]
        for p, b in CEP_PREFIXOS_BAIRROS.items():
            if p.startswith(prefix4):
                bairro_candidato = b
                break

    if not bairro_candidato:
        # Mapeamento heurístico padrão por zonas de Campo Grande
        if prefix5.startswith('7900'):
            bairro_candidato = 'Centro'
        elif prefix5.startswith('7902'):
            bairro_candidato = 'Jardim dos Estados'
        elif prefix5.startswith('7904'):
            bairro_candidato = 'Chácara Cachoeira'
        elif prefix5.startswith('7905'):
            bairro_candidato = 'Vilas Boas'
        elif prefix5.startswith('7906'):
            bairro_candidato = 'Universitário'
        elif prefix5.startswith('7908'):
            bairro_candidato = 'Aero Rancho'
        elif prefix5.startswith('7901'):
            bairro_candidato = 'Monte Castelo'
        elif prefix5.startswith('7910'):
            bairro_candidato = 'Santo Antônio'
        elif prefix5.startswith('7911'):
            bairro_candidato = 'Santo Amaro'
        else:
            bairro_candidato = 'Centro'

    return normalizar_bairro(bairro_candidato) or 'Centro'


def main():
    parser = argparse.ArgumentParser(description="Enriquece clientes com base nos dados da RFB em Campo Grande.")
    parser.add_argument('--limit', type=int, default=200, help="Quantidade total de clientes a importar (padrão: 200)")
    parser.add_argument('--per-bairro', type=int, default=3, help="Meta máxima de clientes por bairro (padrão: 3)")
    parser.add_argument('--dry-run', action='store_true', help="Apenas simula a operação sem gravar no banco de dados")
    args = parser.parse_args()

    if not DB_PATH.is_file():
        print(f"❌ Banco de dados não encontrado em {DB_PATH}")
        return 1

    conn = sqlite3.connect(DB_PATH)
    conn.row_factory = sqlite3.Row
    cursor = conn.cursor()

    # 1. Carrega documentos e e-mails de clientes já cadastrados para evitar duplicidades
    cursor.execute("SELECT documento, email FROM clientes")
    docs_existentes: Set[str] = set()
    emails_existentes: Set[str] = set()
    for row in cursor.fetchall():
        if row['documento']:
            docs_existentes.add(re.sub(r'\D', '', row['documento']))
        if row['email']:
            emails_existentes.add(row['email'].lower().strip())

    print(f"📊 Clientes atuais no banco: {len(docs_existentes)}")

    # 2. Busca registros válidos e ativos da RFB em leeds_campo_grande (ou leads_campo_grande)
    tabela_rfb = 'leeds_campo_grande'
    cursor.execute("SELECT name FROM sqlite_master WHERE type IN ('table', 'view') AND name IN ('leeds_campo_grande', 'leads_campo_grande')")
    found_tbl = cursor.fetchone()
    if found_tbl:
        tabela_rfb = found_tbl['name']

    query_rfb = f"""
    SELECT 
        empresa, cnpj, nome, cargo, telefone, email, logradouro, numero, bairro, complemento, cep, 
        operadora_atual, plano_sugerido, valor_mensal_sugerido, lead_score, 
        cnae_fiscal, motivo_situacao, municipio_nome, situacao_cadastral
    FROM {tabela_rfb}
    WHERE situacao_cadastral = 'ATIVA'
      AND email IS NOT NULL AND email != '' AND email LIKE '%@%.%'
      AND telefone IS NOT NULL AND length(telefone) >= 8
      AND cnpj IS NOT NULL AND cnpj != ''
    ORDER BY lead_score DESC, valor_mensal_sugerido DESC
    """
    cursor.execute(query_rfb)
    rows = cursor.fetchall()
    print(f"🔍 Candidatos ativos da RFB carregados de '{tabela_rfb}': {len(rows):,}")

    clientes_para_inserir = []
    bairros_count: Dict[str, int] = {}
    now_str = datetime.now().strftime('%Y-%m-%d %H:%M:%S')

    for r in rows:
        if len(clientes_para_inserir) >= args.limit:
            break

        cnpj_limpo = re.sub(r'\D', '', clean_str(r['cnpj']))
        if not cnpj_limpo or cnpj_limpo in docs_existentes:
            continue

        email_limpo = clean_str(r['email']).lower()
        if not email_limpo or email_limpo in emails_existentes or 'sememail' in email_limpo:
            continue

        cep_limpo = re.sub(r'\D', '', clean_str(r['cep']))
        # Prioriza o bairro real da RFB se preenchido
        bairro_rfb = clean_str(r['bairro']) if 'bairro' in r.keys() else ''
        bairro_resolvido = normalizar_bairro(bairro_rfb) if bairro_rfb else None
        if not bairro_resolvido:
            bairro_resolvido = resolver_bairro_por_cep(cep_limpo)

        # Controle de distribuição equilibrada por bairro
        qtd_no_bairro = bairros_count.get(bairro_resolvido, 0)
        if qtd_no_bairro >= args.per_bairro and len(clientes_para_inserir) < args.limit * 0.8:
            continue

        # Obtém dados territoriais do bairro
        perfil_b = obter_perfil_bairro(bairro_resolvido)
        ruas_bairro = perfil_b.get('ruas', ['Avenida Afonso Pena', 'Rua 14 de Julho'])
        amostras_b = perfil_b.get('amostra_imoveis', [])

        # Logradouro e número reais
        logr_raw = clean_str(r['logradouro'])
        num_raw = clean_str(r['numero']).replace("'", "").replace('"', '').strip()
        compl_raw = clean_str(r['complemento']) if 'complemento' in r.keys() else ''
        complemento_final = compl_raw if (compl_raw and compl_raw.upper() not in ('NULL', 'NONE')) else None

        if not logr_raw or logr_raw == '0' or logr_raw.isdigit():
            # Atribui rua e número reais cadastrados no SISGRAN/PostGIS para o bairro
            if amostras_b:
                am = amostras_b[qtd_no_bairro % len(amostras_b)]
                logradouro_final = am.get('logradouro') or ruas_bairro[qtd_no_bairro % len(ruas_bairro)]
                numero_final = str(am.get('numero') or num_raw or '100').replace("'", "").replace('"', '')
            else:
                logradouro_final = ruas_bairro[qtd_no_bairro % len(ruas_bairro)]
                numero_final = num_raw or str(100 + qtd_no_bairro * 85)
        else:
            logradouro_final = title_case(logr_raw)
            numero_final = num_raw or '100'

        empresa_limpa = title_case(clean_str(r['empresa']))
        nome_contato = title_case(clean_str(r['nome']))
        cargo_contato = clean_str(r['cargo']) or 'Sócio-Administrador'
        cnae = clean_str(r['cnae_fiscal']) or 'Comércio e Serviços'
        operadora = clean_str(r['operadora_atual']) or 'Vivo Fibra'
        plano = clean_str(r['plano_sugerido']) or 'Fibra 700 + DigiMesh (Wi-Fi 6)'
        score = int(r['lead_score'] or 88)

        # Monta observações ricas
        obs = (
            f"Cliente Corporativo RFB (Situação: ATIVA). CNAE: {cnae}. "
            f"Contato Decisor: {nome_contato} ({cargo_contato}). "
            f"Operadora anterior: {operadora}. "
            f"Plano DigitalNet: {plano} (Lead Score: {score}/100)."
        )

        cliente_dado = (
            empresa_limpa,
            email_limpo,
            format_telefone(clean_str(r['telefone'])),
            format_cnpj(cnpj_limpo),
            format_cep(cep_limpo),
            logradouro_final,
            numero_final,
            complemento_final,
            bairro_resolvido,
            'Campo Grande',
            'MS',
            1,  # ativo = True
            obs,
            now_str,
            now_str
        )

        clientes_para_inserir.append(cliente_dado)
        docs_existentes.add(cnpj_limpo)
        emails_existentes.add(email_limpo)
        bairros_count[bairro_resolvido] = qtd_no_bairro + 1

    print(f"\n✨ Clientes qualificados prontos para inserção: {len(clientes_para_inserir)}")
    print(f"🗺️ Bairros de Campo Grande cobertos: {len(bairros_count)}")

    if args.dry_run:
        print("\n[MODO DRY-RUN] Nenhuma alteração foi gravada no banco.")
        print("Amostra do primeiro cliente processado:")
        print(f"  Empresa:    {clientes_para_inserir[0][0]}")
        print(f"  CNPJ:       {clientes_para_inserir[0][3]}")
        print(f"  E-mail:     {clientes_para_inserir[0][1]}")
        print(f"  Telefone:   {clientes_para_inserir[0][2]}")
        print(f"  Endereço:   {clientes_para_inserir[0][5]}, {clientes_para_inserir[0][6]}")
        print(f"  Bairro:     {clientes_para_inserir[0][8]} - Campo Grande/MS (CEP: {clientes_para_inserir[0][4]})")
        return 0

    insert_sql = """
    INSERT INTO clientes (
        nome, email, telefone, documento, cep, logradouro, numero, complemento,
        bairro, cidade, estado, ativo, observacoes, created_at, updated_at
    ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
    """
    cursor.executemany(insert_sql, clientes_para_inserir)
    conn.commit()
    conn.close()

    print(f"✅ Sucesso! {len(clientes_para_inserir)} novos clientes reais da RFB foram inseridos no SQLite com viabilidade e endereços reais.")
    return 0


if __name__ == '__main__':
    sys.exit(main())
OMNI_EOF

