    "nomeregiao" TEXT,
    "nomebairro" TEXT,
    "areaterren" REAL,
    "arealote" REAL,
    "areaedific" REAL,
    "usoimovel" TEXT,
    "codlogrado" INTEGER,
    "codparcela" INTEGER,
    "inscant_busca" TEXT,
    "codlote_busca" TEXT,
    "logradouro_busca" TEXT,
